/* Pilier M365 : lot 3 — au moins 13 questions par niveau et par sous-thème (52+ par sous-thème), relues par un second passage technique */
window.QUESTIONS.push(
  {"theme":"teams","level":"recrue","format":"single","q":"Tu crées un événement dans le calendrier Outlook et tu veux que les invités puissent le rejoindre en visio. Tu…","a":["actives l'option « Réunion Teams » dans l'invitation","joins un fichier Teams en pièce jointe","ajoutes « Teams » dans le champ Emplacement","envoies le lien de ton profil Teams à part"],"g":0,"e":"Le bouton « Réunion Teams » d'une invitation Outlook génère automatiquement le lien de participation. Écrire « Teams » dans le lieu ne crée aucune réunion en ligne."},
  {"theme":"teams","level":"super","format":"input","q":"Quelle cmdlet du module MicrosoftTeams attribue une stratégie de réunion à un utilisateur ?","placeholder":"Verbe-Nom de la cmdlet","answers":["Grant-CsTeamsMeetingPolicy"],"e":"Les stratégies Teams s'attribuent avec les cmdlets Grant-Cs… ; Set-CsTeamsMeetingPolicy modifie le contenu d'une stratégie, pas son attribution."},
  {"theme":"teams","level":"super","format":"single","q":"Dans le Centre d'administration Teams, où autorises-tu ou interdis-tu l'enregistrement des réunions pour un groupe d'utilisateurs ?","a":["Paramètres à l'échelle de l'organisation > Paramètres Teams","Réunions > Stratégies de réunion","Utilisateurs > Accès externe","Applications Teams > Stratégies de configuration"],"g":1,"e":"L'enregistrement dans le cloud est un paramètre des stratégies de réunion, qu'on attribue ensuite aux utilisateurs ou à des groupes."},
  {"theme":"teams","level":"super","format":"single","q":"Tes utilisateurs ne doivent plus pouvoir discuter dans Teams avec les comptes d'un domaine partenaire précis. Tu vas dans…","a":["Réunions > Paramètres de réunion","Microsoft Entra ID > Paramètres de collaboration externe","Utilisateurs > Accès externe, et tu bloques ce domaine","Applications Teams > Gérer les applications"],"g":2,"e":"L'accès externe (fédération) du Centre d'administration Teams permet d'autoriser ou de bloquer des domaines précis. Les paramètres de collaboration externe d'Entra ID concernent les invités B2B, pas la fédération Teams."},
  {"theme":"teams","level":"super","format":"tf","q":"Une stratégie de configuration d'applications Teams permet d'installer et d'épingler des applications dans la barre latérale Teams des utilisateurs.","a":["Vrai","Faux"],"g":0,"e":"Les stratégies de configuration (Applications Teams > Stratégies de configuration) servent à préinstaller et épingler des applications, et à définir leur ordre dans la barre latérale."},
  {"theme":"teams","level":"super","format":"multi","q":"Quels types de stratégies se gèrent dans le Centre d'administration Teams ? (plusieurs réponses)","a":["Stratégies de réunion","Stratégies d'accès conditionnel","Stratégies de messagerie","Stratégies de configuration d'applications"],"g":[0,2,3],"e":"Réunions, messagerie et configuration d'applications sont des stratégies Teams. L'accès conditionnel se configure dans Microsoft Entra ID, pas dans le Centre d'administration Teams."},
  {"theme":"teams","level":"super","format":"order","q":"Remets dans l'ordre la création d'une équipe en PowerShell :","items":["Install-Module MicrosoftTeams","Connect-MicrosoftTeams","New-Team -DisplayName \"Projet Alpha\"","Add-TeamUser -GroupId <id> -User <UPN>"],"e":"On installe le module, on se connecte au tenant, on crée l'équipe (New-Team renvoie son GroupId), puis on y ajoute des membres avec Add-TeamUser."},
  {"theme":"teams","level":"super","format":"single","q":"Ta conformité exige de conserver les messages des canaux Teams pendant plusieurs années. Tu crées…","a":["une stratégie de messagerie Teams qui interdit la suppression des messages","une règle de transport Exchange qui archive les messages Teams","une stratégie d'expiration des groupes Microsoft 365 réglée sur 5 ans","une stratégie de rétention Purview sur l'emplacement « Messages de canal Teams »"],"g":3,"e":"La conservation des messages Teams passe par les stratégies de rétention de Microsoft Purview, avec des emplacements dédiés aux messages de canal et aux conversations. Une stratégie de messagerie n'empêche pas la suppression côté conformité."},
  {"theme":"teams","level":"super","format":"single","q":"Un utilisateur se plaint d'une réunion Teams hachée hier. Où analyses-tu cette réunion précise ?","a":["Centre d'administration Teams > Utilisateurs > fiche de l'utilisateur > Réunions et appels","Microsoft Purview > Audit > Rechercher dans le journal d'audit","Centre d'administration Microsoft 365 > Intégrité > Intégrité du service","Centre d'administration Exchange > Flux de messagerie > Suivi des messages"],"g":0,"e":"L'analyse des appels, sur la fiche de l'utilisateur, détaille chaque réunion (réseau, appareils, audio). L'intégrité du service ne montre que les incidents globaux Microsoft."},
  {"theme":"teams","level":"super","format":"single","q":"Tu veux que quelques utilisateurs pilotes voient les fonctionnalités Teams en préversion publique. Tu utilises…","a":["une stratégie de réunion dédiée","une stratégie de mise à jour Teams","une licence Teams Premium","le canal Entreprise mensuel de Microsoft 365 Apps"],"g":1,"e":"Les stratégies de mise à jour Teams (Teams > Stratégies de mise à jour Teams) permettent d'activer l'accès à la préversion publique pour les utilisateurs ciblés."},
  {"theme":"teams","level":"legende","format":"single","q":"Quel paramètre de Set-CsTeamsMessagingPolicy empêche les utilisateurs de modifier leurs messages envoyés ?","a":["-AllowOwnerDeleteMessage $false","-AllowEditMessage $false","-AllowUserEditMessage $false","-AllowUserChat $false"],"g":2,"e":"AllowUserEditMessage contrôle la modification des messages envoyés. AllowOwnerDeleteMessage concerne la suppression des messages des autres par les propriétaires, et AllowUserChat coupe toute la conversation privée."},
  {"theme":"teams","level":"legende","format":"input","q":"Tu attribues une stratégie Teams à un groupe avec Grant-CsTeamsMeetingPolicy -Group. Quel paramètre fixe la priorité en cas de conflit entre groupes ?","placeholder":"Nom du paramètre","answers":["-Rank","Rank"],"e":"-Rank définit la priorité de l'attribution de groupe : si un utilisateur appartient à plusieurs groupes, la stratégie du rang le plus prioritaire (1) s'applique."},
  {"theme":"teams","level":"legende","format":"tf","q":"Si un utilisateur a une stratégie de réunion attribuée directement et une autre héritée d'un groupe, c'est la stratégie attribuée directement qui s'applique.","a":["Vrai","Faux"],"g":0,"e":"L'attribution directe l'emporte toujours sur l'héritage de groupe, qui l'emporte lui-même sur la stratégie globale (par défaut de l'organisation)."},
  {"theme":"teams","level":"legende","format":"single","q":"Tu dois attribuer une stratégie Teams à une longue liste d'utilisateurs (sans groupe), en une opération asynchrone suivie. Tu utilises…","a":["Grant-CsTeamsMeetingPolicy -Global","Invoke-CsBulkPolicyAssignment","New-CsGroupPolicyAssignment","New-CsBatchPolicyAssignmentOperation"],"g":3,"e":"New-CsBatchPolicyAssignmentOperation attribue une stratégie à une liste d'identités et renvoie un ID d'opération à suivre avec Get-CsBatchPolicyAssignmentOperation. New-CsGroupPolicyAssignment exige un groupe, et -Global modifie la valeur par défaut du tenant."},
  {"theme":"teams","level":"legende","format":"single","q":"Réglementation oblige : le service Recherche et le service Ventes ne doivent jamais pouvoir se contacter dans Teams. La solution adaptée :","a":["Bloquer les deux services dans l'accès externe","Les obstacles aux informations de Microsoft Purview","Une stratégie DLP sur les conversations Teams","Deux stratégies de messagerie désactivant la conversation"],"g":1,"e":"Les obstacles aux informations (Information Barriers) empêchent la communication et la collaboration entre segments d'utilisateurs internes. L'accès externe ne concerne que les autres organisations."},
  {"theme":"teams","level":"legende","format":"multi","q":"Pour la conformité (eDiscovery, rétention), où Microsoft 365 stocke-t-il ces données Teams ? (plusieurs réponses)","a":["Messages de conversation privée : boîtes aux lettres des participants","Messages de canal standard : boîte aux lettres du groupe Microsoft 365 de l'équipe","Fichiers de canal standard : site SharePoint de l'équipe","Messages de canal standard : OneDrive du propriétaire de l'équipe"],"g":[0,1,2],"e":"Les messages Teams sont copiés dans des boîtes Exchange (celles des participants pour les conversations, celle du groupe pour les canaux standard), et les fichiers de canal vivent dans SharePoint. OneDrive sert aux fichiers partagés en conversation, pas aux messages de canal."},
  {"theme":"teams","level":"legende","format":"single","q":"Quel paramètre de Set-CsTeamsMeetingPolicy règle l'expiration automatique des nouveaux enregistrements de réunion ?","a":["-NewMeetingRecordingExpirationDays","-MeetingRecordingRetentionDays","-AllowCloudRecordingForCalls","-AllowRecordingStorageOutsideRegion"],"g":0,"e":"NewMeetingRecordingExpirationDays fixe le nombre de jours avant expiration des enregistrements stockés dans OneDrive/SharePoint (-1 pour ne jamais expirer). AllowCloudRecordingForCalls concerne l'enregistrement des appels, AllowRecordingStorageOutsideRegion le lieu de stockage ; MeetingRecordingRetentionDays n'existe pas."},
  {"theme":"teams","level":"legende","format":"order","q":"Remets dans l'ordre la mise en place des obstacles aux informations :","items":["Définir les segments avec New-OrganizationSegment","Créer les stratégies avec New-InformationBarrierPolicy","Passer les stratégies à l'état Active","Lancer l'application avec Start-InformationBarrierPoliciesApplication"],"e":"On segmente d'abord les utilisateurs, on crée les stratégies (inactives par défaut), on les active, puis on déclenche leur application, qui peut prendre du temps."},
  {"theme":"teams","level":"legende","format":"tf","q":"Supprimer une équipe Teams supprime aussi le groupe Microsoft 365 associé, qui reste restaurable pendant 30 jours.","a":["Vrai","Faux"],"g":0,"e":"Une équipe repose sur un groupe Microsoft 365 : sa suppression le place en suppression réversible 30 jours, restaurable depuis le Centre d'administration, Entra ID ou PowerShell."},
  {"theme":"teams","level":"legende","format":"single","q":"Tu veux que tes utilisateurs puissent partager leur calendrier avec n'importe quel externe, mais uniquement en disponibilité (libre/occupé), sans objet ni lieu. Tu configures la stratégie de partage avec…","a":["-Domains \"*:CalendarSharingFreeBusyReviewer\"","-Domains \"Anonymous:CalendarSharingFreeBusySimple\"","-Domains \"*:CalendarSharingFreeBusySimple\"","-Domains \"*:CalendarSharingFreeBusyDetail\""],"g":2,"e":"Avec Set-SharingPolicy, « * » vise tous les domaines externes et FreeBusySimple limite à la disponibilité. FreeBusyDetail ajoute l'objet et le lieu, FreeBusyReviewer tous les détails, et « Anonymous » concerne la publication anonyme du calendrier."},
  {"theme":"teams","level":"legende","format":"single","q":"Tu veux interdire la participation anonyme à TOUTES les réunions Teams du tenant, quelle que soit la stratégie de l'organisateur. Tu exécutes…","a":["Set-CsTeamsMeetingPolicy -Identity Global -AllowAnonymousUsersToJoinMeeting $false","Set-CsTeamsMeetingConfiguration -DisableAnonymousJoin $true","Set-CsExternalAccessPolicy -EnableFederationAccess $false","Set-CsTenantFederationConfiguration -AllowPublicUsers $false"],"g":1,"e":"DisableAnonymousJoin, au niveau de la configuration de réunion du tenant, s'applique à toutes les réunions. Modifier la stratégie Global ne touche pas les utilisateurs qui ont une autre stratégie de réunion attribuée."},
  {"theme":"fichiers","level":"recrue","format":"single","q":"Tu veux qu'un collègue puisse lire ton document sans pouvoir le modifier. Dans la fenêtre de partage, tu choisis…","a":["Peut modifier","Peut afficher","Propriétaire","Membre"],"g":1,"e":"« Peut afficher » donne un accès en lecture seule. « Peut modifier » autorise les changements, tandis que « Propriétaire » et « Membre » sont des rôles de site ou de groupe, pas des options d'un lien de partage."},
  {"theme":"fichiers","level":"recrue","format":"tf","q":"Tu peux ouvrir et modifier un fichier Word stocké dans OneDrive directement depuis ton navigateur, même sans avoir Office installé sur le PC.","a":["Vrai","Faux"],"g":0,"e":"Vrai : les applications Office pour le web (Word, Excel, PowerPoint en ligne) s'ouvrent dans le navigateur depuis OneDrive ou SharePoint, sans installation."},
  {"theme":"fichiers","level":"recrue","format":"single","q":"Un fichier de ton OneDrive doit rejoindre la bibliothèque du site SharePoint de ton équipe. Quelle commande utilises-tu ?","a":["Renommer","Télécharger","Déplacer vers","Incorporer"],"g":2,"e":"« Déplacer vers » (ou « Copier vers ») envoie le fichier dans un autre emplacement Microsoft 365, comme la bibliothèque d'un site d'équipe. Télécharger le copie seulement sur ton PC."},
  {"theme":"fichiers","level":"super","format":"single","q":"Tu supprimes le compte d'un utilisateur parti de l'entreprise. Que devient son OneDrive par défaut ?","a":["Il est conservé 93 jours dans la corbeille, sans accès possible","Il est converti en site SharePoint d'équipe rattaché au responsable","Il est déplacé dans le OneDrive de l'administrateur global","Il est conservé 30 jours, et son responsable peut en recevoir l'accès"],"g":3,"e":"La rétention par défaut d'un OneDrive orphelin est de 30 jours (réglable dans le Centre d'administration SharePoint), et l'accès peut être délégué automatiquement au responsable défini dans Entra ID. Passé ce délai, le OneDrive part à la corbeille des sites."},
  {"theme":"fichiers","level":"super","format":"input","q":"Quelle cmdlet ouvre la session SharePoint Online Management Shell vers l'URL d'administration du tenant (https://contoso-admin.sharepoint.com) ?","placeholder":"Nom de la cmdlet","answers":["Connect-SPOService","Connect-SPOService -Url"],"e":"Connect-SPOService -Url https://<tenant>-admin.sharepoint.com est la première commande à lancer avant toute cmdlet *-SPO*."},
  {"theme":"fichiers","level":"super","format":"multi","q":"Quels groupes SharePoint sont créés par défaut sur un site d'équipe ? (plusieurs réponses)","a":["Propriétaires de <site>","Membres de <site>","Invités de <site>","Visiteurs de <site>"],"g":[0,1,3],"e":"Chaque site dispose des groupes Propriétaires (contrôle total), Membres (modification) et Visiteurs (lecture). Il n'existe pas de groupe « Invités » par défaut : les invités sont ajoutés à l'un de ces groupes."},
  {"theme":"fichiers","level":"super","format":"single","q":"Sur un site d'équipe connecté à un groupe Microsoft 365, ajouter quelqu'un comme membre du groupe lui donne…","a":["un accès en modification, via le groupe Membres du site","un accès en lecture seule, via le groupe Visiteurs du site","le contrôle total, via le groupe Propriétaires du site","aucun accès tant qu'un propriétaire ne l'ajoute pas au site"],"g":0,"e":"Les membres du groupe Microsoft 365 héritent du groupe SharePoint Membres (modification), les propriétaires du groupe du groupe Propriétaires. Gérer l'appartenance au groupe est la bonne pratique."},
  {"theme":"fichiers","level":"super","format":"tf","q":"Le Centre d'administration SharePoint permet de n'autoriser la synchronisation OneDrive que sur les PC joints à des domaines précis.","a":["Vrai","Faux"],"g":0,"e":"Vrai : dans Paramètres > Synchronisation, l'option « Autoriser la synchronisation uniquement sur les ordinateurs joints à des domaines spécifiques » attend le GUID du domaine Active Directory."},
  {"theme":"fichiers","level":"super","format":"order","q":"Remets dans l'ordre les étapes pour restaurer un site SharePoint supprimé par erreur :","items":["Ouvrir le Centre d'administration SharePoint","Aller dans Sites > Sites supprimés","Sélectionner le site concerné","Cliquer sur Restaurer"],"e":"Les sites supprimés restent 93 jours dans « Sites supprimés », d'où l'administrateur peut les restaurer avec leur contenu et leurs autorisations."},
  {"theme":"fichiers","level":"super","format":"single","q":"Quelle fonctionnalité OneDrive redirige automatiquement Bureau, Documents et Images vers OneDrive, et peut être imposée par stratégie de groupe ou Intune ?","a":["Fichiers à la demande","Déplacement des dossiers connus","Coffre-fort personnel","Synchronisation différentielle"],"g":1,"e":"Le déplacement des dossiers connus (Known Folder Move) protège ces dossiers Windows dans OneDrive. Fichiers à la demande gère le téléchargement, le Coffre-fort personnel est un dossier protégé par authentification renforcée."},
  {"theme":"fichiers","level":"super","format":"single","q":"Comment est calculé le stockage SharePoint mutualisé d'un tenant Microsoft 365 entreprise ?","a":["1 To par utilisateur licencié, partagé entre tous les sites","25 Go par site, quelle que soit la taille du tenant","1 To + 10 Go par licence éligible","10 Go + 1 To par licence éligible"],"g":2,"e":"Le tenant reçoit 1 To de base plus 10 Go par licence éligible. Ce stockage SharePoint est distinct du stockage OneDrive attribué à chaque utilisateur."},
  {"theme":"fichiers","level":"legende","format":"single","q":"Quel paramètre de Set-SPOTenant change le type de lien proposé par défaut quand un utilisateur clique sur « Partager » ?","a":["-SharingCapability","-DefaultLinkPermission","-DefaultSharingLinkType","-FileAnonymousLinkType"],"g":2,"e":"-DefaultSharingLinkType (None, Direct, Internal, AnonymousAccess) fixe le type de lien par défaut. -DefaultLinkPermission règle seulement l'autorisation par défaut (afficher ou modifier), -SharingCapability le niveau de partage autorisé."},
  {"theme":"fichiers","level":"legende","format":"input","q":"Quelle cmdlet SharePoint Online Management Shell restaure un site encore présent dans la corbeille des sites ?","placeholder":"Nom de la cmdlet","answers":["Restore-SPODeletedSite"],"e":"Restore-SPODeletedSite -Identity <URL> restaure le site supprimé. Get-SPODeletedSite liste les sites récupérables, Remove-SPODeletedSite les purge définitivement."},
  {"theme":"fichiers","level":"legende","format":"single","q":"Tu veux que tous les liens « Toute personne disposant du lien » expirent automatiquement après 30 jours. Quel paramètre de Set-SPOTenant utilises-tu ?","a":["-ExternalUserExpireInDays","-RequireAnonymousLinksExpireInDays","-EmailAttestationReAuthDays","-AnonymousLinkExpirationDays"],"g":1,"e":"-RequireAnonymousLinksExpireInDays impose une expiration aux liens anonymes. -ExternalUserExpireInDays concerne l'expiration de l'accès des invités, -EmailAttestationReAuthDays la revérification par code des utilisateurs externes."},
  {"theme":"fichiers","level":"legende","format":"tf","q":"Avec Set-SPOSite -SharingCapability, tu ne peux pas rendre un site plus permissif que le niveau de partage défini au niveau du tenant.","a":["Vrai","Faux"],"g":0,"e":"Vrai : le paramètre du tenant est un plafond. Un site peut être plus restrictif que l'organisation, jamais plus ouvert."},
  {"theme":"fichiers","level":"legende","format":"multi","q":"Quelles valeurs sont valides pour le paramètre -SharingCapability de Set-SPOTenant ? (plusieurs réponses)","a":["ExistingExternalUserSharingOnly","AnonymousLinkSharing","ExternalUserAndGuestSharing","OrganizationOnly"],"g":[0,2],"e":"Les valeurs valides sont Disabled, ExistingExternalUserSharingOnly, ExternalUserSharingOnly et ExternalUserAndGuestSharing (cette dernière autorise les liens anonymes). AnonymousLinkSharing et OrganizationOnly n'existent pas : le partage interne seul correspond à Disabled."},
  {"theme":"fichiers","level":"legende","format":"single","q":"Pour que les appareils non gérés n'aient qu'un accès web limité (sans téléchargement ni synchronisation) à SharePoint et OneDrive, quelle valeur donnes-tu à Set-SPOTenant -ConditionalAccessPolicy ?","a":["AllowFullAccess","BlockAccess","WebOnlyAccess","AllowLimitedAccess"],"g":3,"e":"AllowLimitedAccess active l'accès web limité, appliqué via une stratégie d'accès conditionnel Entra ID. BlockAccess bloque totalement, et WebOnlyAccess n'est pas une valeur existante."},
  {"theme":"fichiers","level":"legende","format":"order","q":"Remets dans l'ordre la mise en place d'un site hub et le rattachement d'un premier site :","items":["Connect-SPOService -Url https://contoso-admin.sharepoint.com","New-SPOSite -Url <URL du hub> -Template SITEPAGEPUBLISHING#0 -Owner <UPN> -StorageQuota 1024 -Title \"Hub\"","Register-SPOHubSite -Site <URL du hub>","Add-SPOHubSiteAssociation -Site <URL du site> -HubSite <URL du hub>"],"e":"On se connecte, on crée le site de communication (modèle SITEPAGEPUBLISHING#0, avec un quota de stockage obligatoire), on l'enregistre comme hub avec Register-SPOHubSite, puis seulement on lui associe des sites avec Add-SPOHubSiteAssociation."},
  {"theme":"fichiers","level":"legende","format":"single","q":"Pour que SharePoint et OneDrive traitent le contenu des fichiers Office chiffrés par une étiquette de confidentialité (coédition, recherche, eDiscovery), tu actives…","a":["Set-SPOTenant -EnableAIPIntegration $true","Set-SPOTenant -EnableSensitivityLabelforPDF $true","EnableMIPLabels dans les paramètres de groupe Entra ID","Set-SPOSite -SensitivityLabel sur chaque site"],"g":0,"e":"-EnableAIPIntegration active la prise en charge des étiquettes de confidentialité pour les fichiers Office dans SharePoint et OneDrive. EnableMIPLabels sert aux étiquettes de conteneurs (groupes, sites), et le paramètre PDF ne concerne que les PDF."},
  {"theme":"fichiers","level":"legende","format":"single","q":"Pour supprimer en masse les anciennes versions déjà existantes des fichiers d'un site et récupérer du stockage, tu utilises…","a":["Set-SPOSite -MajorVersionLimit 100","New-SPOSiteFileVersionBatchDeleteJob","Set-SPOSite -EnableAutoExpirationVersionTrim $true","Remove-SPOFileVersion -All"],"g":1,"e":"New-SPOSiteFileVersionBatchDeleteJob lance un travail de suppression des versions existantes. Les paramètres de limite de versions de Set-SPOSite s'appliquent aux versions à venir et ne purgent pas l'historique déjà stocké."},
  {"theme":"fichiers","level":"legende","format":"single","q":"Quel paramètre de Set-SPOTenant allonge la durée de conservation du OneDrive d'un utilisateur supprimé ?","a":["-OrphanedPersonalSitesRetentionPeriod","-OneDriveRequestFilesLinkExpirationInDays","-DeletedPersonalSitesRetentionDays","-DeletedUserPersonalSiteRetention"],"g":0,"e":"-OrphanedPersonalSitesRetentionPeriod (en jours, de 30 à 3650) définit combien de temps le OneDrive d'un utilisateur supprimé est conservé. Il correspond au paramètre de rétention du Centre d'administration SharePoint. -OneDriveRequestFilesLinkExpirationInDays concerne les liens « Demander des fichiers »."},
  {"theme":"productivite","level":"recrue","format":"single","q":"Dans PowerPoint, tu veux que les puces d'une diapositive apparaissent une par une pendant le diaporama. Tu utilises…","a":["l'onglet Transitions","l'onglet Animations","le masque des diapositives","le mode Présentateur"],"g":1,"e":"Les animations s'appliquent aux éléments d'une diapositive (texte, images) et règlent leur apparition. Les transitions, elles, gèrent le passage d'une diapositive à la suivante."},
  {"theme":"productivite","level":"recrue","format":"tf","q":"Dans Word, le raccourci Ctrl+Entrée insère un saut de page.","a":["Vrai","Faux"],"g":0,"e":"Ctrl+Entrée insère un saut de page : le texte suivant commence en haut de la page suivante. C'est plus propre que d'enchaîner des retours à la ligne, qui décalent tout dès que tu modifies le texte au-dessus."},
  {"theme":"productivite","level":"recrue","format":"single","q":"Dans Excel, une cellule affiche #DIV/0!. Que se passe-t-il ?","a":["La colonne est trop étroite pour afficher le nombre","La formule contient une faute de frappe dans le nom de la fonction","La formule essaie de diviser par zéro ou par une cellule vide","La cellule fait référence à une feuille supprimée"],"g":2,"e":"#DIV/0! signale une division par zéro (ou par une cellule vide). Une colonne trop étroite affiche des #####, un nom de fonction mal écrit donne #NOM?, et une référence supprimée donne #REF!."},
  {"theme":"productivite","level":"recrue","format":"input","q":"Dans PowerPoint, quelle touche du clavier lance le diaporama depuis la première diapositive ?","placeholder":"Nom de la touche","answers":["F5"],"e":"F5 lance le diaporama depuis le début. Maj+F5 le lance à partir de la diapositive affichée."},
  {"theme":"productivite","level":"recrue","format":"single","q":"Dans PowerPoint, le « masque des diapositives » sert à…","a":["Définir une mise en forme commune à toutes les diapositives","Masquer une diapositive pendant le diaporama sans la supprimer du fichier","Protéger la présentation par un mot de passe à l'ouverture","Afficher les notes de l'orateur sur ton écran pendant la présentation"],"g":0,"e":"Le masque des diapositives (Affichage > Masque des diapositives) définit la mise en page et le style (polices, logo, couleurs) de toutes les diapositives d'un coup. Pour cacher une diapositive, on utilise « Masquer la diapositive », qui n'a rien à voir."},
  {"theme":"productivite","level":"recrue","format":"multi","q":"Quelles extensions correspondent aux formats de fichier actuels de Word, Excel et PowerPoint ? (plusieurs réponses)","a":[".docx",".pdf",".xlsx",".pptx"],"g":[0,2,3],"e":".docx, .xlsx et .pptx sont les formats Office modernes (basés sur XML). Le .pdf est un format d'export pour diffuser un document figé, pas le format natif d'une app Office."},
  {"theme":"productivite","level":"hero","format":"order","q":"Remets dans l'ordre les étapes pour restaurer une version précédente d'un document Word stocké sur OneDrive :","items":["Ouvrir le document dans Word","Aller dans Fichier > Informations > Historique des versions","Ouvrir la version antérieure voulue pour la vérifier","Cliquer sur « Restaurer »"],"e":"Pour un fichier stocké sur OneDrive ou SharePoint, l'historique des versions conserve les états précédents. Tu ouvres la version voulue pour la vérifier, puis tu la restaures : elle devient la version actuelle, et la version remplacée reste dans l'historique."},
  {"theme":"productivite","level":"hero","format":"single","q":"Dans Word, où lances-tu le vérificateur d'accessibilité ?","a":["Onglet Insertion > Vérifier l'accessibilité","Onglet Affichage > Mode Lecture","Onglet Révision > Vérifier l'accessibilité","Onglet Mise en page > Accessibilité"],"g":2,"e":"Le vérificateur se trouve dans l'onglet Révision. Il signale par exemple les images sans texte de remplacement, les contrastes insuffisants ou les tableaux sans ligne d'en-tête."},
  {"theme":"productivite","level":"hero","format":"input","q":"Dans Excel, quel raccourci insère la date du jour (valeur fixe) dans la cellule active ?","placeholder":"Ex. : Ctrl+…","answers":["Ctrl+;","Ctrl+point-virgule","Ctrl ;","Ctrl + ;"],"e":"Ctrl+; insère la date du jour sous forme de valeur fixe, qui ne changera plus. À l'inverse, la fonction =AUJOURDHUI() se recalcule chaque jour."},
  {"theme":"productivite","level":"hero","format":"tf","q":"Le texte de remplacement (alt text) ajouté à une image sert surtout à la décrire aux personnes qui utilisent un lecteur d'écran.","a":["Vrai","Faux"],"g":0,"e":"Le texte de remplacement est lu par les lecteurs d'écran pour décrire l'image aux personnes malvoyantes. Une image purement décorative peut être marquée « Décoratif » pour qu'elle soit ignorée."},
  {"theme":"productivite","level":"super","format":"single","q":"Tu dois déployer les Apps Microsoft 365 en choisissant les applications, la langue et le canal de mise à jour. Quel outil Microsoft utilises-tu ?","a":["Le Programme d'installation Windows (msiexec) avec un fichier .msi","L'Outil de déploiement d'Office (ODT) avec un fichier configuration.xml","L'Assistant de support et de récupération Microsoft (SaRA)","Le Centre d'administration Microsoft Entra, rubrique Applications"],"g":1,"e":"L'Outil de déploiement d'Office (setup.exe) lit un fichier configuration.xml qui décrit les applications, la langue, l'architecture et le canal. Les Apps Microsoft 365 s'installent en Démarrer en un clic (Click-to-Run), pas via un .msi."},
  {"theme":"productivite","level":"super","format":"input","q":"Quel outil web de Microsoft (config.office.com) permet de générer graphiquement le fichier configuration.xml de l'ODT ?","placeholder":"Nom de l'outil","answers":["Office Customization Tool","Outil de personnalisation d'Office","Outil de personnalisation Office","OCT","Office Customization Tool (OCT)","Outil de personnalisation d'Office (OCT)"],"e":"L'Office Customization Tool, accessible depuis config.office.com, génère le fichier configuration.xml à partir d'un formulaire. C'est plus sûr que d'écrire le XML à la main."},
  {"theme":"productivite","level":"super","format":"multi","q":"Quels canaux de mise à jour existent pour les Apps Microsoft 365 for enterprise ? (plusieurs réponses)","a":["Canal actuel","Canal Entreprise mensuel","Canal de maintenance à long terme (LTSC)","Canal Windows Insider Dev"],"g":[0,1],"e":"Les Apps Microsoft 365 proposent le Canal actuel et le Canal Entreprise mensuel (plus des canaux de préversion). Depuis la version 2606 (juillet 2026), le Canal Entreprise semi-annuel est unifié avec le Canal Entreprise mensuel. Le LTSC concerne Office LTSC, une version perpétuelle, et le canal Windows Insider concerne Windows, pas Office.","maj":{"date":"2026-07-14","texte":"Microsoft unifie le Canal Entreprise semi-annuel avec le Canal Entreprise mensuel : mises à jour mensuelles pour tous (version 2606).","source":"Microsoft Learn","url":"https://learn.microsoft.com/en-us/microsoft-365-apps/updates/overview-update-channels"}},
  {"theme":"productivite","level":"super","format":"single","q":"Tu veux empêcher les utilisateurs d'installer eux-mêmes les apps Office de bureau depuis leur portail. Où le configures-tu ?","a":["Centre d'administration Microsoft Entra > Applications d'entreprise > Paramètres utilisateur","Portail Microsoft Purview > Protection des informations > Étiquettes","Centre d'administration Microsoft Intune > Appareils > Conformité des appareils","Centre d'administration Microsoft 365 > Paramètres de l'organisation > Options d'installation"],"g":3,"e":"Dans le centre d'administration Microsoft 365, les options d'installation de Microsoft 365 (Paramètres de l'organisation > Services) permettent de choisir les applications que les utilisateurs peuvent installer eux-mêmes. Tu peux alors déployer toi-même les apps, avec Intune ou l'ODT par exemple."},
  {"theme":"productivite","level":"super","format":"single","q":"Quel service applique des stratégies Office (paramètres Word, Excel, etc.) aux utilisateurs, même sur des appareils personnels non joints au domaine ?","a":["Les stratégies de groupe (GPO) avec les modèles ADMX Office","Le service Cloud Policy du centre d'administration Microsoft 365 Apps","Les stratégies de conformité Intune","Les stratégies DLP de Microsoft Purview"],"g":1,"e":"Le service Cloud Policy (config.office.com) applique les stratégies Office à l'utilisateur dès qu'il se connecte avec son compte professionnel, quel que soit l'appareil. Les GPO exigent des machines jointes à Active Directory, et les stratégies de conformité Intune évaluent l'état de l'appareil sans configurer les applications Office."},
  {"theme":"productivite","level":"super","format":"tf","q":"Avec une licence incluant les Apps Microsoft 365, chaque utilisateur peut installer les apps de bureau sur jusqu'à 5 PC ou Mac, 5 tablettes et 5 smartphones.","a":["Vrai","Faux"],"g":0,"e":"Chaque utilisateur sous licence peut installer les apps sur 5 PC ou Mac, 5 tablettes et 5 smartphones. Pour des machines partagées (RDS, Azure Virtual Desktop), on utilise l'activation d'ordinateurs partagés."},
  {"theme":"productivite","level":"super","format":"single","q":"Quelle fonction Excel permet de nommer des résultats intermédiaires à l'intérieur d'une formule pour éviter de les recalculer ?","a":["LAMBDA","CHOISIR","INDIRECT","LET"],"g":3,"e":"LET associe des noms à des valeurs ou à des calculs dans la formule, par exemple =LET(x;A1*2;x+x). La formule devient plus lisible et plus rapide. LAMBDA sert à créer des fonctions personnalisées réutilisables."},
  {"theme":"productivite","level":"super","format":"order","q":"Remets dans l'ordre un déploiement des Apps Microsoft 365 avec l'Outil de déploiement d'Office :","items":["Télécharger et extraire l'Outil de déploiement d'Office","Créer le fichier configuration.xml (par exemple avec l'Office Customization Tool)","Exécuter setup.exe /download configuration.xml pour télécharger les sources","Exécuter setup.exe /configure configuration.xml pour installer"],"e":"On récupère d'abord setup.exe, puis on décrit l'installation dans configuration.xml. Le mode /download précharge les fichiers sur un partage local, et le mode /configure lance l'installation selon ce fichier."},
  {"theme":"productivite","level":"legende","format":"input","q":"Quel commutateur de setup.exe (Outil de déploiement d'Office) lance l'installation selon le fichier configuration.xml ?","placeholder":"Ex. : /…","answers":["/configure","configure"],"e":"setup.exe /configure configuration.xml installe (ou modifie) les Apps selon le fichier. /download télécharge seulement les sources, et /packager sert à créer un package App-V."},
  {"theme":"productivite","level":"legende","format":"single","q":"Dans configuration.xml, comment exclus-tu Access d'une installation des Apps Microsoft 365 ?","a":["<RemoveApp ID=\"Access\" /> à la racine de <Configuration>","<Disable App=\"Access\" /> dans l'élément <Updates>","<ExcludeApp ID=\"Access\" /> dans l'élément <Product>","<Exclude Product=\"Access\" /> dans l'élément <Add>"],"g":2,"e":"L'élément ExcludeApp, placé dans Product, empêche l'installation d'une application précise (Access, OneNote, Teams, etc.). Les autres éléments proposés n'existent pas dans le schéma ODT."},
  {"theme":"productivite","level":"legende","format":"single","q":"Quel Product ID indiques-tu dans configuration.xml pour installer Microsoft 365 Apps for enterprise ?","a":["O365BusinessRetail","O365ProPlusRetail","M365EnterpriseRetail","ProPlus2024Volume"],"g":1,"e":"Microsoft 365 Apps for enterprise correspond au Product ID O365ProPlusRetail, hérité de l'ancien nom « Office 365 ProPlus ». O365BusinessRetail correspond à Microsoft 365 Apps for business, et ProPlus2024Volume à Office LTSC Professional Plus 2024."},
  {"theme":"productivite","level":"legende","format":"tf","q":"Depuis la version 2606 (juillet 2026), les postes configurés sur le Canal Entreprise semi-annuel reçoivent chaque mois les mêmes mises à jour que le Canal Entreprise mensuel.","a":["Vrai","Faux"],"g":0,"e":"Vrai : Microsoft a unifié le Canal Entreprise semi-annuel avec le Canal Entreprise mensuel. Les postes reçoivent les nouveautés et les correctifs chaque mois (le 2e mardi) et s'affichent comme Canal Entreprise mensuel dans Fichier > Compte. Le rythme janvier/juillet a pris fin.","maj":{"date":"2026-07-14","texte":"Microsoft unifie le Canal Entreprise semi-annuel avec le Canal Entreprise mensuel : mises à jour mensuelles pour tous (version 2606).","source":"Microsoft Learn","url":"https://learn.microsoft.com/en-us/microsoft-365-apps/updates/overview-update-channels","avant":[1]}},
  {"theme":"productivite","level":"legende","format":"multi","q":"Quelles affirmations sur l'activation d'ordinateurs partagés des Apps Microsoft 365 sont exactes ? (plusieurs réponses)","a":["Elle s'active dans configuration.xml avec la propriété SharedComputerLicensing à 1","Elle vise notamment les environnements RDS et Azure Virtual Desktop","Elle fonctionne avec une licence Microsoft 365 Business Basic","Elle ne compte pas dans la limite d'installations de l'utilisateur"],"g":[0,1,3],"e":"L'activation d'ordinateurs partagés (<Property Name=\"SharedComputerLicensing\" Value=\"1\" />) permet à plusieurs utilisateurs sous licence d'utiliser la même machine sans consommer leurs installations. Business Basic n'inclut pas les apps de bureau, donc cette licence ne suffit pas."},
  {"theme":"productivite","level":"legende","format":"single","q":"Dans RECHERCHEX, quelle valeur du 5e argument (mode_correspondance) active les caractères génériques * et ? ?","a":["-1","1","2","0"],"g":2,"e":"Le mode 2 active les caractères génériques. 0 (par défaut) demande une correspondance exacte, -1 accepte la valeur exacte ou l'élément inférieur suivant, et 1 la valeur exacte ou l'élément supérieur suivant."},
  {"theme":"productivite","level":"legende","format":"single","q":"Un classeur créé dans une ancienne version d'Excel s'ouvre dans Excel pour Microsoft 365 et certaines formules affichent un @ devant une référence. Que signifie ce @ ?","a":["La formule est protégée et ne peut pas être modifiée","L'intersection implicite : la formule ne renvoie qu'une seule valeur, comme dans l'ancien Excel","La référence pointe vers une mention de collègue dans un commentaire","La formule est une formule matricielle héritée à valider par Ctrl+Maj+Entrée"],"g":1,"e":"Avec les tableaux dynamiques, Excel ajoute @ pour conserver l'ancien comportement d'intersection implicite, qui ne renvoie qu'une valeur au lieu de propager un tableau. Sans @, la formule pourrait déborder sur plusieurs cellules."},
  {"theme":"productivite","level":"legende","format":"single","q":"Des utilisateurs ne peuvent pas co-éditer en temps réel des documents chiffrés par une étiquette de confidentialité. Quelle action d'admin règle ce problème ?","a":["Accorder le droit Copropriétaire à tous dans l'étiquette","Activer dans Purview la co-édition des fichiers chiffrés par étiquette","Désactiver l'enregistrement automatique dans le service Cloud Policy","Passer tous les postes au Canal Entreprise semi-annuel"],"g":1,"e":"Microsoft Purview propose un paramètre au niveau du locataire qui active la co-édition et l'enregistrement automatique pour les fichiers chiffrés par une étiquette. Les versions des Apps doivent le prendre en charge. Élargir les droits de l'étiquette ou changer de canal de mise à jour ne débloque pas la co-édition."},
  {"theme":"productivite","level":"legende","format":"order","q":"Remets dans l'ordre la création d'une configuration dans le service Cloud Policy :","items":["Se connecter au centre d'administration Microsoft 365 Apps (config.office.com)","Ouvrir la gestion des stratégies et créer une configuration de stratégie","Nommer la configuration et choisir son étendue (groupe d'utilisateurs)","Rechercher et configurer les paramètres de stratégie voulus","Enregistrer la configuration pour qu'elle s'applique aux utilisateurs"],"e":"Une configuration Cloud Policy cible un groupe d'utilisateurs, puis on y active les paramètres. Les Apps récupèrent périodiquement les stratégies du compte connecté, sans qu'il soit nécessaire de joindre la machine au domaine."},
  {"theme":"productivite","level":"legende","format":"single","q":"Dans configuration.xml, quelle valeur de l'attribut Channel correspond au Canal Entreprise mensuel ?","a":["Monthly","EnterpriseMonthly","MonthlyEnterprise","Broad"],"g":2,"e":"Les valeurs recommandées sont Current, MonthlyEnterprise et SemiAnnual (ce dernier suit le rythme mensuel depuis l'unification de juillet 2026). Monthly et Broad sont d'anciens noms, encore acceptés mais à éviter dans une nouvelle configuration. EnterpriseMonthly n'existe pas.","maj":{"date":"2026-07-14","texte":"Microsoft unifie le Canal Entreprise semi-annuel avec le Canal Entreprise mensuel : la valeur SemiAnnual suit désormais le rythme mensuel.","source":"Microsoft Learn","url":"https://learn.microsoft.com/en-us/microsoft-365-apps/updates/overview-update-channels"}},
  {"theme":"productivite","level":"legende","format":"single","q":"Tu as écrit une fonction LAMBDA et tu veux l'appeler par son nom partout dans le classeur. Que fais-tu ?","a":["Tu l'enregistres comme macro dans un module VBA","Tu la places dans une cellule masquée et tu y fais référence avec INDIRECT","Tu l'ajoutes comme complément .xlam dans les options Excel","Tu la définis comme nom dans le Gestionnaire de noms"],"g":3,"e":"Une LAMBDA se nomme dans le Gestionnaire de noms (Formules > Gestionnaire de noms). Tu l'appelles ensuite comme une fonction native, par exemple =MaFonction(A2), sans VBA."},
  {"theme":"copilot","level":"recrue","format":"input","q":"Comment appelle-t-on la question ou l'instruction que tu écris à Copilot ?","placeholder":"Un mot…","answers":["prompt","invite","requête","requete","un prompt","le prompt","une invite","prompts","consigne","une consigne"],"e":"Le prompt (ou invite) est la demande que tu formules à Copilot. Plus il est clair et précis, plus la réponse est utile."},
  {"theme":"copilot","level":"recrue","format":"single","q":"Copilot t'affiche avec assurance un chiffre ou une citation qui n'existe nulle part dans tes documents. Comment appelle-t-on ce phénomène ?","a":["Un bug d'affichage","Une fuite de données","Une hallucination","Un conflit de version"],"g":2,"e":"Une IA générative peut produire une information plausible mais fausse : on parle d'hallucination. C'est pour ça qu'on vérifie toujours les faits importants avant de les réutiliser."},
  {"theme":"copilot","level":"recrue","format":"tf","q":"Si tu poses exactement la même question deux fois à Copilot, tu obtiens toujours mot pour mot la même réponse.","a":["Vrai","Faux"],"g":1,"e":"Faux : Copilot génère un nouveau texte à chaque demande, la formulation peut donc varier d'une fois à l'autre. Ce n'est pas un dysfonctionnement."},
  {"theme":"copilot","level":"recrue","format":"single","q":"Dans une réponse de Copilot, à quoi servent les références (citations) affichées sous le texte ?","a":["À noter la réponse de 1 à 5","À retrouver et vérifier les sources utilisées","À partager la réponse à ton équipe","À traduire la réponse dans une autre langue"],"g":1,"e":"Les références renvoient vers les documents, mails ou pages sur lesquels Copilot s'est appuyé. Un clic suffit pour contrôler que la réponse colle bien à la source."},
  {"theme":"copilot","level":"recrue","format":"single","q":"Tu voudrais utiliser Microsoft 365 Copilot dans Word et Outlook avec ton compte pro. En entreprise, qui t'attribue normalement la licence nécessaire ?","a":["Toi-même, depuis les paramètres de Word","N'importe quel collègue qui a déjà la licence","Le support Microsoft, par téléphone","Un administrateur de ton organisation"],"g":3,"e":"Microsoft 365 Copilot est une licence que l'entreprise achète et qu'un administrateur attribue. Selon les réglages de l'admin, Copilot Chat peut aussi te proposer de demander une licence ou de l'acheter en libre-service (depuis 2025), voire un essai gratuit de 30 jours dans les PME de 300 postes au plus (depuis l'été 2026). Mais jamais une activation depuis les paramètres de Word.","maj":{"date":"2025-03-01","precision":"mois","texte":"Microsoft permet aux utilisateurs de demander ou d'acheter eux-mêmes une licence Microsoft 365 Copilot, si l'admin l'autorise.","source":"Message Center Microsoft 365","url":"https://mc.merill.net/message/MC1017114"}},
  {"theme":"copilot","level":"recrue","format":"multi","q":"La réponse de Copilot ne te convient pas (trop longue, ton trop formel). Que peux-tu faire ? (plusieurs réponses)","a":["Lui demander une version plus courte","Lui demander de réentraîner son modèle sur tes mails","Préciser le ton voulu dans une nouvelle demande","Le menacer de passer chez la concurrence"],"g":[0,2],"e":"Copilot fonctionne en conversation : tu affines avec des demandes de suivi (plus court, plus simple, autre ton…). Il ne se « réentraîne » pas sur tes mails, et les menaces ne l'impressionnent pas."},
  {"theme":"copilot","level":"recrue","format":"order","q":"Remets dans l'ordre les étapes pour rédiger un document avec Copilot dans Word :","items":["Ouvrir Copilot dans le document Word","Écrire un prompt qui décrit le document voulu","Lire le brouillon proposé","Affiner avec une demande de suivi si besoin","Conserver le texte puis le relire avant de le diffuser"],"e":"On demande, on lit, on ajuste, puis on garde. La relecture finale reste indispensable : c'est toi qui es responsable du document diffusé."},
  {"theme":"copilot","level":"recrue","format":"single","q":"Tu commences ton prompt par « Agis comme un formateur qui s'adresse à des débutants ». À quoi ça sert ?","a":["À adapter le ton et le niveau de la réponse","À donner à Copilot des droits supplémentaires","À enregistrer ce rôle dans ton profil Microsoft 365","À partager la conversation avec les débutants"],"g":0,"e":"Donner un rôle et un public cible aide Copilot à choisir le vocabulaire, le niveau de détail et le ton. Ça ne modifie ni tes droits ni ton profil."},
  {"theme":"copilot","level":"hero","format":"single","q":"Un utilisateur veut que Copilot lui résume une réunion Teams après sa fin, mais Copilot n'a rien à exploiter. Quelle est la cause la plus courante ?","a":["La réunion comptait trop de participants pour que Copilot l'analyse","Ni la transcription ni le récapitulatif IA n'ont été activés pour la réunion","La réunion a été planifiée depuis Outlook et non depuis Teams","L'utilisateur n'était pas l'organisateur de la réunion"],"g":1,"e":"Après la réunion, Copilot s'appuie sur la transcription. Depuis fin octobre 2026, l'organisateur peut aussi activer, dans les options « Copilot et autres IA », un récapitulatif sans enregistrer la transcription. Sans l'un ni l'autre, Copilot n'est utilisable que pendant la réunion.","maj":{"date":"2026-10-01","precision":"mois","texte":"Microsoft Teams propose un récapitulatif IA de réunion sans transcription ni enregistrement (licence Microsoft 365 Copilot).","source":"Message Center Microsoft 365","url":"https://mc.merill.net/message/MC1275312"}},
  {"theme":"copilot","level":"hero","format":"tf","q":"Un agent Copilot branché sur un site SharePoint ne répond à chaque utilisateur qu'à partir des contenus que cet utilisateur a le droit de consulter.","a":["Vrai","Faux"],"g":0,"e":"Vrai : l'agent interroge les sources avec l'identité de la personne qui l'utilise. Deux collègues peuvent donc obtenir des réponses différentes s'ils n'ont pas les mêmes droits sur le site."},
  {"theme":"copilot","level":"hero","format":"single","q":"À quoi sert Copilot Pages ?","a":["À créer des sites SharePoint à partir d'un prompt","À programmer l'envoi automatique de réponses Copilot par mail","À transformer une réponse de Copilot en page modifiable et partageable","À afficher l'historique des prompts de toute l'organisation"],"g":2,"e":"Copilot Pages permet de reprendre une réponse de Copilot dans une page collaborative que tu peux enrichir et partager avec tes collègues pour y travailler à plusieurs."},
  {"theme":"copilot","level":"hero","format":"multi","q":"Quels principes font partie des principes d'IA responsable affichés par Microsoft ? (plusieurs réponses)","a":["Équité","Transparence","Exhaustivité","Responsabilité"],"g":[0,1,3],"e":"Microsoft retient six principes : équité, fiabilité et sécurité, confidentialité et sécurité, inclusion, transparence et responsabilité. « Exhaustivité » n'en fait pas partie."},
  {"theme":"copilot","level":"hero","format":"single","q":"Ticket support : la licence Microsoft 365 Copilot vient d'être attribuée à Léa, mais le bouton Copilot n'apparaît pas dans Word sur son PC. Que vérifies-tu d'abord ?","a":["Que son PC est un PC Copilot+ équipé d'une puce NPU","Que Léa a aussi une licence Teams Premium active sur son compte","Que Léa a bien le rôle d'administrateur global","Que Word est à jour, connecté au compte pro, puis redémarré"],"g":3,"e":"L'application doit être connectée avec le compte qui porte la licence et être à jour ; un redémarrage de l'appli aide à récupérer la licence. Ni PC Copilot+ ni Teams Premium ne sont nécessaires, et l'attribution peut mettre un peu de temps à se propager."},
  {"theme":"copilot","level":"hero","format":"tf","q":"Avec Copilot Chat, même sans licence Microsoft 365 Copilot, tu peux joindre un fichier à la conversation pour qu'il l'analyse.","a":["Vrai","Faux"],"g":0,"e":"Vrai : Copilot Chat peut travailler sur un fichier que tu lui fournis. Sans licence Microsoft 365 Copilot, son accès à tes données de travail reste limité (un ancrage restreint existe dans Outlook) ; la recherche large dans tes mails, fichiers et réunions via Microsoft Graph est réservée à la licence payante."},
  {"theme":"copilot","level":"hero","format":"single","q":"De quoi se compose principalement un agent déclaratif dans Microsoft 365 Copilot ?","a":["D'un script PowerShell exécuté à chaque question","D'instructions, de sources de connaissances et éventuellement d'actions","D'une copie complète des boîtes mail de l'équipe","D'un modèle d'IA entraîné sur les données de l'entreprise"],"g":1,"e":"Un agent déclaratif décrit ce qu'il doit faire (instructions), où il cherche l'information (connaissances comme des sites SharePoint) et ce qu'il peut exécuter (actions). Il s'appuie sur le même moteur que Copilot, sans réentraîner de modèle."},
  {"theme":"copilot","level":"super","format":"input","q":"Avec Microsoft Graph PowerShell, quelle cmdlet liste les licences (SKU) du tenant pour retrouver le SkuId de Microsoft 365 Copilot ?","placeholder":"Verbe-Nom…","answers":["Get-MgSubscribedSku"],"e":"Get-MgSubscribedSku renvoie les abonnements du tenant avec leur SkuId, leur SkuPartNumber et le nombre de licences consommées. Ce SkuId sert ensuite à Set-MgUserLicense."},
  {"theme":"copilot","level":"super","format":"single","q":"L'attribution de la licence Copilot par PowerShell échoue sur des comptes créés par script. Quelle est la cause classique ?","a":["Le compte n'a pas encore de boîte aux lettres Exchange","Le compte n'est membre d'aucune équipe Teams","La propriété UsageLocation n'est pas renseignée","Le compte n'a jamais ouvert de session dans Outlook"],"g":2,"e":"Une licence ne peut pas être attribuée à un utilisateur sans emplacement d'utilisation (UsageLocation), car la disponibilité des services dépend du pays. On le définit par exemple avec Update-MgUser -UsageLocation. La boîte Exchange, elle, est créée après l'attribution de la licence."},
  {"theme":"copilot","level":"super","format":"single","q":"Tu dois donner la licence Copilot à 200 personnes et suivre les arrivées et départs sans script. Quelle approche est la plus maintenable ?","a":["Attribuer la licence une par une dans Utilisateurs actifs","Utiliser l'attribution de licences par groupe dans Microsoft Entra ID","Créer une règle de flux de messagerie dans Exchange","Déployer un profil de configuration Intune"],"g":1,"e":"Avec les licences par groupe, tout membre du groupe reçoit la licence et la perd en sortant du groupe. Combiné à un groupe dynamique ou géré par les RH, c'est l'option la plus simple à maintenir."},
  {"theme":"copilot","level":"super","format":"single","q":"Un utilisateur demande à Copilot de rédiger un nouveau document Word à partir d'un fichier étiqueté « Confidentiel ». Que devient l'étiquette de sensibilité ?","a":["Le nouveau document ne porte aucune étiquette","Le nouveau document reçoit l'étiquette par défaut du tenant","Copilot refuse de créer le document","Le nouveau document hérite de l'étiquette « Confidentiel »"],"g":3,"e":"Copilot applique l'héritage des étiquettes : le contenu créé à partir de fichiers étiquetés reprend l'étiquette de priorité la plus élevée parmi les sources. La protection suit donc l'information."},
  {"theme":"copilot","level":"super","format":"order","q":"Remets dans l'ordre les grandes étapes d'un déploiement Microsoft 365 Copilot :","items":["Vérifier les prérequis (licences de base, applications Microsoft 365, comptes)","Auditer et corriger le surpartage dans SharePoint et OneDrive","Lancer un pilote avec un groupe restreint","Attribuer les licences à plus grande échelle","Suivre l'adoption avec les rapports d'utilisation"],"e":"On sécurise l'accès aux données avant d'ouvrir Copilot, on teste sur un petit groupe, puis on étend et on mesure. Copilot révélant tout ce que les gens peuvent déjà voir, le nettoyage des permissions passe avant l'élargissement."},
  {"theme":"copilot","level":"super","format":"single","q":"Où un admin consulte-t-il nativement l'utilisation de Microsoft 365 Copilot (utilisateurs actifs, applications utilisées) ?","a":["Centre d'administration Microsoft 365 > Rapports > Utilisation","Centre d'administration Exchange > Flux de messagerie","Centre d'administration Intune > Appareils > Conformité","Centre d'administration Entra > Journaux de connexion"],"g":0,"e":"Les rapports d'utilisation du centre d'administration Microsoft 365 incluent un rapport dédié à Microsoft 365 Copilot. Les journaux de connexion Entra montrent des authentifications, pas l'usage de Copilot par application."},
  {"theme":"copilot","level":"super","format":"multi","q":"Quels outils servent à gouverner les agents créés avec Copilot Studio ? (plusieurs réponses)","a":["Les règles de transport du centre d'administration Exchange","Les environnements gérés dans le centre d'administration Power Platform","Les stratégies de données (DLP) Power Platform sur les connecteurs","Les anneaux de mise à jour Windows dans Intune"],"g":[1,2],"e":"Copilot Studio repose sur Power Platform : les environnements cloisonnent les agents et les stratégies DLP limitent les connecteurs utilisables. Les règles de transport Exchange et les anneaux Windows Update n'ont aucun effet sur les agents."},
  {"theme":"copilot","level":"super","format":"single","q":"Dans le cadre d'une enquête juridique, tu dois retrouver les prompts et réponses Copilot d'un utilisateur. Quel outil utilises-tu ?","a":["Le journal d'activité de SharePoint","L'historique de Microsoft Edge","Microsoft Purview eDiscovery","Le centre d'administration Teams"],"g":2,"e":"Les interactions Copilot sont conservées dans le service et peuvent être recherchées, mises en conservation et exportées avec Microsoft Purview eDiscovery, comme les mails ou les conversations Teams."},
  {"theme":"copilot","level":"super","format":"single","q":"Avant d'ouvrir Copilot, tu veux repérer les sites SharePoint surpartagés (liens trop larges, accès à toute l'organisation). Quelle fonctionnalité t'aide à les identifier ?","a":["Les rapports de messages en quarantaine du portail Defender","Les rapports de gouvernance d'accès aux données de SharePoint","Le rapport d'activité des fichiers OneDrive du centre d'admin","Le tableau de bord Secure Score et ses recommandations"],"g":1,"e":"Les rapports de gouvernance de l'accès aux données (SharePoint Advanced Management) listent notamment les sites avec beaucoup de liens de partage ou ouverts à toute l'organisation. C'est une base concrète pour cibler le nettoyage."},
  {"theme":"copilot","level":"legende","format":"single","q":"Un document est chiffré par une étiquette de sensibilité. Quels droits d'utilisation l'utilisateur doit-il avoir pour que Copilot puisse s'appuyer sur son contenu ?","a":["Uniquement VIEW (Afficher)","VIEW (Afficher) et EXTRACT (Copier)","EDIT (Modifier) et PRINT (Imprimer)","Uniquement OWNER (Propriétaire)"],"g":1,"e":"Pour qu'un contenu chiffré soit utilisé par Copilot, l'utilisateur doit disposer des droits VIEW et EXTRACT. Une étiquette qui retire le droit de copie empêche donc Copilot de résumer le contenu, même si l'utilisateur peut l'ouvrir."},
  {"theme":"copilot","level":"legende","format":"input","q":"Un document partagé contient du texte caché qui ordonne à l'IA d'ignorer ses consignes et d'exfiltrer des données. Comment appelle-t-on ce type d'attaque ?","placeholder":"Nom de l'attaque…","answers":["injection de prompt","prompt injection","injection d'invite","injection de prompt indirecte","injection de prompts"],"e":"C'est une injection de prompt (dite indirecte quand l'instruction malveillante se cache dans un contenu traité par l'IA). Microsoft intègre des protections contre ces attaques, mais le principe du moindre privilège reste la meilleure limite."},
  {"theme":"copilot","level":"legende","format":"single","q":"Microsoft retire Restricted SharePoint Search (plus de nouvelle activation depuis juillet 2026, retrait complet fin janvier 2027). Que doit faire un admin qui l'utilisait pour limiter Copilot ?","a":["Rien : la configuration sera migrée automatiquement","Appliquer lui-même la découverte de contenu restreinte aux sites sensibles","Retirer toutes les licences Copilot jusqu'au retrait complet","Passer les sites concernés en lecture seule pour les masquer à Copilot"],"g":1,"e":"La configuration n'est pas migrée automatiquement : sans action, du contenu jusque-là restreint pourrait redevenir visible dans Copilot. On applique la découverte de contenu restreinte (Restricted Content Discovery, SharePoint Advanced Management) aux sites sensibles, et on corrige les permissions en parallèle. La lecture seule n'empêche pas Copilot de lire un site.","maj":{"date":"2026-07-31","texte":"Microsoft bloque toute nouvelle activation de Restricted SharePoint Search, qui cessera de fonctionner le 31 janvier 2027.","source":"Microsoft Learn","url":"https://learn.microsoft.com/en-us/sharepoint/restricted-sharepoint-search"}},
  {"theme":"copilot","level":"legende","format":"single","q":"Lors d'un audit de surpartage avant Copilot, quelle attribution de permission est l'un des signaux les plus fréquents d'exposition trop large ?","a":["Le groupe « Tout le monde sauf les utilisateurs externes »","Le groupe « Propriétaires » du site, avec contrôle total","Les membres de l'équipe Teams associée au site SharePoint","Un lien « Personnes spécifiques » envoyé à un collègue"],"g":0,"e":"« Tout le monde sauf les utilisateurs externes » donne l'accès à tous les comptes internes du tenant. Copilot pouvant faire remonter tout ce qu'un utilisateur peut lire, ces sites sont à revoir en priorité."},
  {"theme":"copilot","level":"legende","format":"tf","q":"Les interactions des utilisateurs avec Microsoft 365 Copilot sont enregistrées dans l'audit de Microsoft Purview et peuvent y être recherchées.","a":["Vrai","Faux"],"g":0,"e":"Vrai : l'audit Purview journalise les interactions Copilot (activité CopilotInteraction), avec l'utilisateur, l'application et les ressources consultées. Le contenu des prompts et réponses, lui, se recherche avec eDiscovery."},
  {"theme":"copilot","level":"legende","format":"single","q":"Quand Microsoft 365 Copilot s'appuie sur le web pour compléter une réponse, qu'est-ce qui est envoyé au service de recherche Bing ?","a":["Le prompt complet et les fichiers cités","L'intégralité de la conversation en cours","Une requête de recherche générée à partir du prompt","Rien : Copilot n'utilise jamais le web"],"g":2,"e":"Copilot génère une courte requête de recherche à partir du prompt et l'envoie à Bing ; les documents et la conversation entière ne sont pas transmis. Les admins peuvent en plus contrôler l'accès au web par stratégie."},
  {"theme":"copilot","level":"legende","format":"single","q":"Tu veux empêcher Copilot de traiter les fichiers portant l'étiquette « Hautement confidentiel », même pour les utilisateurs qui y ont accès. Quelle solution Microsoft Purview utilises-tu ?","a":["Une stratégie de rétention appliquée à l'emplacement Copilot","Une stratégie Communication Compliance sur les interactions Copilot","Une stratégie DLP avec l'emplacement Microsoft 365 Copilot","Une étiquette de rétention qui déclare le fichier comme enregistrement"],"g":2,"e":"Purview DLP propose un emplacement dédié à Microsoft 365 Copilot qui permet d'exclure des réponses les contenus portant certaines étiquettes. La rétention et les enregistrements gèrent la conservation, Communication Compliance surveille les échanges : aucun n'empêche Copilot d'utiliser le contenu."},
  {"theme":"copilot","level":"legende","format":"order","q":"Remets dans l'ordre le traitement d'une demande par Microsoft 365 Copilot :","items":["L'utilisateur saisit son prompt dans une application Microsoft 365","Copilot récupère via Microsoft Graph les données auxquelles l'utilisateur a accès (ancrage)","Le prompt enrichi est envoyé au grand modèle de langage","La réponse passe par un post-traitement (contrôles d'IA responsable, sécurité, conformité)","La réponse est renvoyée à l'application, avec ses références"],"e":"L'ancrage dans Graph a lieu avant l'appel au modèle, et un post-traitement filtre la réponse avant de l'afficher. C'est ce circuit qui garantit le respect des permissions de l'utilisateur."},
  {"theme":"copilot","level":"legende","format":"single","q":"Avec Microsoft Graph PowerShell, quelle commande retire la licence Copilot ($sku) de l'utilisateur $u ?","a":["Set-MgUserLicense -UserId $u -AddLicenses @() -RemoveLicenses @($sku)","Remove-MgUserLicense -UserId $u -SkuId $sku -Confirm:$false","Set-MgUserLicense -UserId $u -RemoveLicenses @($sku) -Confirm:$false","Update-MgUser -UserId $u -AssignedLicenses @{RemoveLicenses=@($sku)}"],"g":0,"e":"Set-MgUserLicense exige les deux paramètres -AddLicenses et -RemoveLicenses : pour un simple retrait, on passe un tableau vide à -AddLicenses. Remove-MgUserLicense n'existe pas, et AssignedLicenses ne se modifie pas via Update-MgUser."},
  {"theme":"copilot","level":"legende","format":"single","q":"Un agent Copilot Studio est publié avec l'option « Aucune authentification ». Quelle conséquence dois-tu anticiper ?","a":["L'agent n'est visible que par les administrateurs de l'environnement Power Platform","Tout utilisateur du canal peut s'en servir, sans identité pour interroger SharePoint","L'agent hérite automatiquement des droits de son créateur sur tous les sites SharePoint","L'agent reste bloqué tant qu'une licence Copilot n'est pas attribuée à chaque visiteur"],"g":1,"e":"Sans authentification, l'agent ne sait pas qui lui parle : il est ouvert à quiconque atteint le canal et ne peut pas interroger des sources qui exigent l'identité de l'utilisateur, comme SharePoint. À réserver aux contenus réellement publics."},
  {"theme":"exchange","level":"recrue","format":"single","q":"Dans le nouvel Outlook, où crées-tu ta signature de mail ?","a":["Paramètres > Comptes > Signatures","Paramètres > Général > Apparence","Affichage > Disposition > Volet de lecture","Paramètres > Calendrier > Événements"],"g":0,"e":"La signature se gère dans Paramètres > Comptes > Signatures. Tu peux en créer plusieurs et choisir celle qui s'ajoute par défaut aux nouveaux messages et aux réponses."},
  {"theme":"exchange","level":"recrue","format":"tf","q":"Une réponse automatique d'absence peut envoyer un message différent aux personnes externes à ton entreprise.","a":["Vrai","Faux"],"g":0,"e":"Outlook permet de définir un message pour tes collègues et un autre pour l'extérieur, voire de ne répondre qu'à tes contacts externes. Pratique pour ne pas donner trop de détails aux inconnus."},
  {"theme":"exchange","level":"recrue","format":"single","q":"Tu veux repérer d'un coup d'œil, par une couleur, tous les mails liés au projet Alpha. Dans Outlook, tu utilises…","a":["les catégories","l'importance haute","la Boîte de réception Prioritaire","les réponses automatiques"],"g":0,"e":"Les catégories associent un nom et une couleur aux messages (et aux rendez-vous) : tu peux ensuite trier ou rechercher par catégorie. L'importance haute signale un mail urgent au destinataire, sans rien classer chez toi."},
  {"theme":"exchange","level":"recrue","format":"single","q":"On t'a donné accès à la boîte partagée support@. Comment l'afficher dans Outlook sur le web ?","a":["Te déconnecter, puis te reconnecter avec l'identifiant et le mot de passe de support@","Clic droit sur « Dossiers » > « Ajouter un dossier partagé ou une boîte aux lettres »","Créer une règle de boîte de réception qui transfère les mails de support@ vers toi","Demander à l'admin un export PST de la boîte, puis l'ouvrir dans Outlook"],"g":1,"e":"Dans Outlook sur le web, un clic droit sur « Dossiers » permet d'ajouter une boîte partagée à laquelle tu as accès. Elle apparaît alors dans ton volet de dossiers, sans mot de passe séparé."},
  {"theme":"exchange","level":"recrue","format":"single","q":"Un mail attendu d'un fournisseur a atterri dans « Courrier indésirable ». Que fais-tu ?","a":["Tu le supprimes et demandes au fournisseur de le renvoyer","Tu le transfères à ton adresse perso","Tu le déplaces dans Brouillons","Tu le marques comme « Non indésirable »"],"g":3,"e":"Marquer le message comme non indésirable le remet dans la boîte de réception et aide le filtre à ne plus classer cet expéditeur en indésirable. Le supprimer ne règle rien pour les prochains mails."},
  {"theme":"exchange","level":"recrue","format":"multi","q":"Quelles actions une règle de boîte de réception Outlook peut-elle faire automatiquement ? (plusieurs réponses)","a":["Déplacer le message dans un dossier","Modifier le texte du message reçu","Marquer le message comme lu","Transférer le message à quelqu'un"],"g":[0,2,3],"e":"Une règle peut classer, marquer comme lu, catégoriser ou transférer un message selon des conditions (expéditeur, objet…). Elle ne réécrit pas le contenu d'un mail reçu."},
  {"theme":"exchange","level":"recrue","format":"single","q":"Tu partages ton calendrier avec un collègue mais il ne doit voir que tes créneaux libres ou occupés. Quelle autorisation choisis-tu ?","a":["Peut modifier","Peut afficher quand je suis occupé","Peut afficher tous les détails","Délégué"],"g":1,"e":"« Peut afficher quand je suis occupé » ne montre que la disponibilité, sans objet ni lieu. Les autres niveaux donnent accès aux détails, voire à la modification."},
  {"theme":"exchange","level":"recrue","format":"single","q":"Tu as le droit d'envoyer depuis support@. Dans un nouveau message Outlook, comment faire ?","a":["Écrire « support@ » au début de l'objet","Mettre support@ en copie du message","Afficher le champ « De » et y choisir support@","Changer ton nom d'affichage dans ton profil"],"g":2,"e":"Le champ « De » n'est pas toujours affiché par défaut : une fois visible, tu y sélectionnes l'adresse de la boîte partagée. Mettre support@ en copie ne change pas l'expéditeur."},
  {"theme":"exchange","level":"recrue","format":"input","q":"Dans Outlook pour Windows, depuis ta boîte de réception, quel raccourci clavier crée un nouveau message ?","placeholder":"Ex. : Ctrl+…","answers":["Ctrl+N","Ctrl + N","Ctrl N","CtrlN"],"e":"Ctrl+N ouvre un nouvel élément du type de la vue en cours : un nouveau mail depuis la boîte de réception, un nouveau rendez-vous depuis le calendrier."},
  {"theme":"exchange","level":"recrue","format":"order","q":"Remets dans l'ordre les étapes pour activer ta réponse automatique dans le nouvel Outlook :","items":["Ouvrir les Paramètres (roue dentée)","Aller dans Comptes > Réponses automatiques","Activer les réponses automatiques","Rédiger le message et, si besoin, définir la période","Enregistrer"],"e":"La réponse automatique se règle dans Paramètres > Comptes > Réponses automatiques. En fixant une période, elle s'arrête toute seule à ton retour."},
  {"theme":"exchange","level":"recrue","format":"single","q":"Dans Outlook, que fait le bouton « Archiver » sur un mail ?","a":["Il le supprime définitivement","Il le déplace dans le dossier Archive, hors de la boîte de réception","Il le déplace dans la boîte d'archive en ligne d'Exchange Online","Il le compresse en fichier ZIP pour gagner de la place"],"g":1,"e":"« Archiver » range le message dans le dossier Archive : ta boîte de réception reste propre et le mail reste consultable et trouvable par la recherche."},
  {"theme":"exchange","level":"recrue","format":"single","q":"Tu as supprimé un mail par erreur ce matin. Où le cherches-tu en premier ?","a":["Dans Brouillons","Dans Éléments envoyés","Dans Courrier indésirable","Dans Éléments supprimés"],"g":3,"e":"Un mail supprimé part d'abord dans « Éléments supprimés », d'où tu peux le remettre dans la boîte de réception. S'il a été vidé de ce dossier, « Récupérer les éléments supprimés » permet encore souvent de le retrouver."},
  {"theme":"exchange","level":"recrue","format":"tf","q":"Une boîte aux lettres partagée a son propre mot de passe, que chaque membre de l'équipe utilise pour s'y connecter.","a":["Vrai","Faux"],"g":1,"e":"Chaque membre accède à la boîte partagée avec son propre compte, grâce aux autorisations données par l'admin. On ne partage pas de mot de passe, ce qui garde aussi la traçabilité."},
  {"theme":"exchange","level":"hero","format":"single","q":"Dans Outlook sur le web, quelle option te laisse quelques secondes pour annuler un mail juste après avoir cliqué sur « Envoyer » ?","a":["Rappeler ce message","Différer la remise","Annuler l'envoi","Enregistrer comme brouillon"],"g":2,"e":"« Annuler l'envoi » (Paramètres > Courrier > Composer et répondre) retient le message quelques secondes, le temps de cliquer sur Annuler. Le rappel agit après l'envoi et seulement dans ton organisation, sans garantie de succès."},
  {"theme":"exchange","level":"hero","format":"single","q":"Un salarié quitte l'entreprise ; son manager doit continuer à consulter ses mails. Bonne pratique courante ?","a":["Réinitialiser son mot de passe et le transmettre au manager","Convertir sa boîte en boîte partagée et donner l'accès au manager","Exporter sa boîte en PST sur le poste du manager","Supprimer le compte et restaurer la boîte plus tard"],"g":1,"e":"Convertir la boîte en boîte partagée garde les mails accessibles aux personnes autorisées, sans partager de mot de passe, et libère souvent la licence (sauf besoins comme l'archivage ou une conservation spécifique)."},
  {"theme":"exchange","level":"hero","format":"single","q":"Pour lire facilement les en-têtes d'un mail suspect (serveurs traversés, SPF, DKIM…), quel outil Microsoft utilises-tu ?","a":["L'analyseur d'en-têtes de message (Message Header Analyzer)","Le suivi des messages (message trace) d'Exchange","Les rapports de flux de courrier d'Exchange","L'Assistant Support et récupération (SaRA)"],"g":0,"e":"L'analyseur d'en-têtes (dans Microsoft Remote Connectivity Analyzer ou en complément Outlook) met en forme les en-têtes : délais entre serveurs, résultats SPF/DKIM/DMARC, score anti-spam."},
  {"theme":"exchange","level":"hero","format":"single","q":"L'admin a donné l'accès total à une boîte partagée via un groupe de sécurité. Elle n'apparaît pas toute seule dans Outlook classique. Pourquoi ?","a":["La boîte partagée n'a pas de licence Exchange Online attribuée","Outlook classique n'affiche les boîtes partagées qu'en mode en ligne","Le mode Exchange mis en cache doit d'abord être désactivé sur le poste","Le mappage automatique ne s'applique pas à un accès donné via un groupe"],"g":3,"e":"Le mappage automatique (AutoMapping) ne fonctionne que pour une autorisation donnée directement à l'utilisateur. Via un groupe, chacun doit ajouter la boîte manuellement dans Outlook."},
  {"theme":"exchange","level":"hero","format":"tf","q":"Un groupe de contacts que tu crées dans tes contacts Outlook apparaît automatiquement dans la liste d'adresses globale, pour tous tes collègues.","a":["Vrai","Faux"],"g":1,"e":"Faux : un groupe de contacts est personnel, il n'existe que dans tes contacts. Pour une liste visible de toute l'organisation, l'admin crée une liste de distribution ou un groupe Microsoft 365."},
  {"theme":"exchange","level":"hero","format":"order","q":"Remets dans l'ordre la création d'une règle de boîte de réception dans le nouvel Outlook :","items":["Ouvrir Paramètres > Courrier > Règles","Cliquer sur « Ajouter une nouvelle règle »","Nommer la règle","Définir la condition puis l'action","Enregistrer la règle"],"e":"Les règles se gèrent dans Paramètres > Courrier > Règles. Une règle = un nom, au moins une condition (expéditeur, objet…) et au moins une action (déplacer, transférer…)."},
  {"theme":"exchange","level":"hero","format":"input","q":"Dans Outlook pour Windows, quel raccourci clavier bascule directement vers le calendrier ?","placeholder":"ex. Ctrl+…","answers":["Ctrl+2","Ctrl + 2","Ctrl 2","Ctrl2"],"e":"Ctrl+2 ouvre le calendrier, Ctrl+1 revient au courrier et Ctrl+3 ouvre les contacts. Pratique pour passer d'une vue à l'autre sans la souris."},
  {"theme":"exchange","level":"hero","format":"single","q":"Un utilisateur reçoit un rapport de non-remise (NDR) avec le code 5.1.1. Cause la plus probable ?","a":["La boîte aux lettres du destinataire est pleine (quota dépassé)","L'adresse du destinataire est incorrecte ou n'existe pas","La pièce jointe dépasse la taille maximale autorisée","Le destinataire a activé une réponse automatique d'absence"],"g":1,"e":"Le code 5.1.1 signale un destinataire introuvable : faute de frappe, adresse supprimée ou ancienne entrée dans la saisie semi-automatique. Première chose à faire : vérifier l'adresse. Une boîte pleine ou un message trop gros donnent d'autres codes (5.2.2, 5.3.4)."},
  {"theme":"exchange","level":"hero","format":"single","q":"Tu organises une réunion avec six collègues. Quel outil d'Outlook montre leurs disponibilités côte à côte pour trouver un créneau ?","a":["La Boîte de réception Prioritaire","Les réponses automatiques","L'accès délégué","L'Assistant Planification"],"g":3,"e":"L'Assistant Planification affiche les créneaux libres et occupés des participants (et des salles) sur une même grille, pour choisir un horaire qui convient à tous."},
  {"theme":"exchange","level":"super","format":"single","q":"En PowerShell Exchange Online, quelle commande convertit la boîte d'un utilisateur en boîte partagée ?","a":["Set-Mailbox -Identity jdupont -Type Shared","New-SharedMailbox -From jdupont","Convert-Mailbox -Identity jdupont -Shared","Set-User -Identity jdupont -Mailbox Shared"],"g":0,"e":"Set-Mailbox avec -Type Shared change le type de la boîte sans perdre son contenu. Les autres cmdlets proposées n'existent pas."},
  {"theme":"exchange","level":"super","format":"multi","q":"Quels mécanismes DNS aident à lutter contre l'usurpation de ton domaine de messagerie ? (plusieurs réponses)","a":["SPF","DKIM","Enregistrement MX","DMARC"],"g":[0,1,3],"e":"SPF liste les serveurs autorisés à envoyer, DKIM signe les messages, DMARC indique quoi faire en cas d'échec et envoie des rapports. Le MX indique seulement où livrer le courrier entrant."},
  {"theme":"exchange","level":"legende","format":"input","q":"Ton script Exchange Online tourne dans un runbook Azure Automation, sans mot de passe ni certificat stocké. Quel paramètre de Connect-ExchangeOnline utilise l'identité managée du compte Automation ?","placeholder":"-Paramètre","answers":["-ManagedIdentity","ManagedIdentity"],"e":"Connect-ExchangeOnline -ManagedIdentity -Organization contoso.onmicrosoft.com s'authentifie avec l'identité managée (système ou, avec -ManagedIdentityAccountId, attribuée par l'utilisateur). L'identité doit avoir la permission Exchange.ManageAsApp et un rôle Entra adapté."},
  {"theme":"exchange","level":"legende","format":"single","q":"Par défaut, les éléments supprimés récupérables sont conservés 14 jours. Comment passer au maximum autorisé pour une boîte ?","a":["Set-Mailbox -RetainDeletedItemsFor 30","Set-Mailbox -RetainDeletedItemsFor 90","Set-MailboxFolder -DeletedItemsRetention 30","Set-OrganizationConfig -DeletedItemRetention 365"],"g":0,"e":"RetainDeletedItemsFor se règle par boîte (ou via Set-MailboxPlan pour les nouvelles) avec un maximum de 30 jours. Pour garder plus longtemps, on passe par la rétention Microsoft Purview ou une conservation pour litige."},
  {"theme":"exchange","level":"legende","format":"single","q":"Tu donnes FullAccess sur une boîte à un utilisateur, mais elle ne doit pas s'ajouter automatiquement à son Outlook. Quelle commande ?","a":["Add-MailboxPermission -Identity support -User jdupont -AccessRights FullAccess -InheritanceType None","Add-MailboxPermission -Identity support -User jdupont -AccessRights FullAccess -AutoMapping $false","Add-RecipientPermission -Identity support -Trustee jdupont -AccessRights FullAccess","Set-Mailbox -Identity support -AutoMapping $false -GrantFullAccess jdupont"],"g":1,"e":"Le paramètre -AutoMapping $false d'Add-MailboxPermission empêche l'ajout automatique dans Outlook classique. Add-RecipientPermission sert au droit SendAs, et Set-Mailbox n'a pas de paramètre AutoMapping."},
  {"theme":"exchange","level":"legende","format":"tf","q":"Dans Exchange Online, le droit « Envoyer en tant que » (SendAs) sur une boîte s'accorde avec Add-RecipientPermission, et non avec Add-ADPermission.","a":["Vrai","Faux"],"g":0,"e":"Add-ADPermission est réservé à Exchange Server sur site. En ligne, on utilise Add-RecipientPermission -AccessRights SendAs -Trustee <utilisateur>."},
  {"theme":"exchange","level":"legende","format":"single","q":"Quelle commande donne à jdupont le droit « Envoyer de la part de » sur la boîte support@ ?","a":["Add-RecipientPermission -Identity support -Trustee jdupont -AccessRights SendOnBehalf","Add-MailboxPermission -Identity support -User jdupont -AccessRights SendOnBehalf","Set-Mailbox -Identity support -GrantSendOnBehalfTo @{Add='jdupont'}","Set-MailboxDelegate -Identity support -SendOnBehalf jdupont"],"g":2,"e":"« Envoyer de la part de » est une propriété de la boîte : Set-Mailbox -GrantSendOnBehalfTo, ici avec la syntaxe @{Add=…} pour ne pas écraser les délégués existants. SendOnBehalf n'est pas une valeur valide d'AccessRights."},
  {"theme":"exchange","level":"legende","format":"multi","q":"Parmi ces cmdlets, lesquelles existent réellement dans Exchange Online PowerShell ? (plusieurs réponses)","a":["Get-EXOMailbox","Get-MessageTraceV2","Set-MailboxOutOfOffice","Set-MailboxAutoReplyConfiguration"],"g":[0,1,3],"e":"Get-EXOMailbox est la cmdlet optimisée du module V3, Get-MessageTraceV2 remplace l'ancien Get-MessageTrace, et la réponse automatique se règle avec Set-MailboxAutoReplyConfiguration. Set-MailboxOutOfOffice n'existe pas."},
  {"theme":"exchange","level":"legende","format":"order","q":"Remets dans l'ordre un déploiement DMARC prudent pour un domaine :","items":["Publier SPF et activer DKIM","Publier DMARC en p=none avec une adresse de rapports (rua)","Analyser les rapports et corriger les sources légitimes en échec","Passer en p=quarantine","Passer en p=reject"],"e":"On commence en observation (p=none) pour repérer les expéditeurs légitimes mal configurés, puis on durcit progressivement. Passer directement en p=reject risque de bloquer des mails légitimes (outils marketing, applications métier…)."},
  {"theme":"exchange","level":"legende","format":"single","q":"Où publie-t-on l'enregistrement DMARC du domaine contoso.com ?","a":["Un TXT sur contoso.com, à côté du SPF","Un CNAME sur selector1._domainkey.contoso.com","Un MX secondaire sur dmarc.contoso.com","Un TXT sur _dmarc.contoso.com"],"g":3,"e":"DMARC se publie en TXT sur le sous-domaine _dmarc (ex. « v=DMARC1; p=none; rua=mailto:… »). Les CNAME selector1/selector2._domainkey servent à DKIM, et le TXT à la racine porte le SPF."},
  {"theme":"exchange","level":"legende","format":"tf","q":"Dans Outlook classique pour Windows, une règle qui affiche une alerte ou joue un son à l'arrivée d'un mail ne s'exécute que lorsque Outlook est ouvert.","a":["Vrai","Faux"],"g":0,"e":"Certaines actions dépendent du client (son, alerte, déplacement vers un PST…) : la règle devient « côté client uniquement ». Les règles purement serveur (déplacer, transférer…) s'exécutent même Outlook fermé. Le nouvel Outlook ne propose que des règles côté serveur."},
  {"theme":"exchange","level":"legende","format":"single","q":"Tu veux masquer une boîte aux lettres de la liste d'adresses globale (GAL) sans la supprimer. Quelle commande ?","a":["Set-Mailbox -Identity compta -HiddenFromAddressListsEnabled $true","Set-Mailbox -Identity compta -GALVisible $false","Set-Recipient -Identity compta -ShowInAddressBook None","Remove-AddressListMember -Identity compta -List GAL"],"g":0,"e":"HiddenFromAddressListsEnabled $true retire la boîte de la GAL et des listes d'adresses : elle continue de recevoir des mails. Les autres paramètres et cmdlets proposés n'existent pas en Exchange Online."},
  {"theme":"admin","level":"recrue","format":"single","q":"Concrètement, c'est quoi une licence Microsoft 365 ?","a":["La clé produit à 25 caractères à saisir dans Word ou Excel","Un droit d'utilisation attribué à ton compte, qui débloque des services","Le fichier d'installation d'Office à télécharger sur ton PC","Le compte Microsoft personnel créé avec ton adresse pro"],"g":1,"e":"Une licence (Microsoft 365 E3, Business Premium…) est attribuée à un compte et lui donne accès à des services comme Exchange, Teams ou OneDrive. Sans licence, le compte existe mais ne peut pas utiliser ces services."},
  {"theme":"admin","level":"recrue","format":"single","q":"Premier jour : tu te connectes, mais Outlook t'indique que ta boîte aux lettres est introuvable. Cause la plus probable ?","a":["Ton écran est trop petit pour afficher Outlook","Ton mot de passe provisoire n'a pas encore été changé à la première connexion","Ton PC n'est pas encore inscrit dans Intune par le support","Aucune licence avec Exchange Online n'est encore attribuée à ton compte"],"g":3,"e":"La boîte aux lettres Exchange Online est créée quand une licence qui l'inclut est attribuée. Un compte tout neuf sans licence peut se connecter mais n'a pas encore de boîte."},
  {"theme":"admin","level":"recrue","format":"tf","q":"Ton compte professionnel (prenom.nom@entreprise.fr) et un compte Microsoft personnel (Outlook.com, Hotmail) sont la même chose.","a":["Vrai","Faux"],"g":1,"e":"Ce sont deux types de comptes distincts : le compte professionnel est géré par ton organisation dans Microsoft Entra ID, le compte personnel t'appartient. Sur l'écran de connexion, choisis toujours « compte professionnel ou scolaire » pour le travail."},
  {"theme":"admin","level":"recrue","format":"single","q":"Tu as besoin d'une licence supplémentaire (Visio, par exemple) pour ton travail. À qui t'adresses-tu ?","a":["Au support informatique ou à l'administrateur de ton organisation","Directement au support Microsoft","À un collègue qui a déjà Visio, pour qu'il te prête son compte","À personne : tu installes une version d'essai trouvée sur Internet"],"g":0,"e":"Les licences sont achetées et attribuées par ton organisation : passe par le support interne. Partager un compte est interdit et dangereux, et le support Microsoft ne traite qu'avec les administrateurs du tenant."},
  {"theme":"admin","level":"recrue","format":"single","q":"Où un utilisateur peut-il voir lui-même les licences et abonnements attribués à son compte ?","a":["Dans le Centre de messages","Dans le Microsoft Store","Sur la page Mon compte (myaccount.microsoft.com), rubrique Abonnements","Dans le centre d'administration Microsoft 365, rubrique Facturation"],"g":2,"e":"La page Mon compte liste les abonnements du compte professionnel, sans droits d'admin. Le Centre de messages et la rubrique Facturation du centre d'admin sont réservés aux administrateurs."},
  {"theme":"admin","level":"recrue","format":"single","q":"Dans le vocabulaire Microsoft 365, que désigne un « tenant » (locataire) ?","a":["Un utilisateur invité venant d'une autre entreprise partenaire","L'espace Microsoft 365 de ton organisation (comptes, domaines, données)","Un serveur physique Microsoft installé dans les locaux de l'entreprise","Le nom commercial de l'offre Microsoft 365 E5 pour les grandes entreprises"],"g":1,"e":"Chaque organisation dispose de son propre tenant, isolé des autres. Tous les comptes, licences, domaines et paramètres de l'entreprise y sont rattachés."},
  {"theme":"admin","level":"recrue","format":"single","q":"Dans une entreprise, qui attribue normalement les licences Microsoft 365 aux employés ?","a":["Chaque employé, depuis Word au premier lancement","Le stagiaire, avec le mot de passe admin trouvé sous le clavier","Microsoft, automatiquement dès l'embauche","Un administrateur ayant le rôle adapté (licences ou utilisateurs)"],"g":3,"e":"L'attribution se fait dans le centre d'administration Microsoft 365 (ou par groupe) par un admin ayant un rôle comme Administrateur des licences ou Administrateur des utilisateurs."},
  {"theme":"admin","level":"recrue","format":"multi","q":"Un service ne fonctionne pas. Quelles informations utiles donnes-tu au support ? (plusieurs réponses)","a":["Le message d'erreur exact ou une capture d'écran","Le service concerné et l'heure du problème","Ton mot de passe, pour qu'il teste à ta place","Si des collègues ont le même souci"],"g":[0,1,3],"e":"Message d'erreur, service, heure et nombre de personnes touchées aident à diagnostiquer vite (panne générale ou problème de compte). Un technicien ne te demandera jamais ton mot de passe."},
  {"theme":"admin","level":"recrue","format":"single","q":"Plusieurs collègues n'arrivent plus à ouvrir Outlook en même temps. Quel est le bon premier réflexe ?","a":["Réinstaller Outlook sur ton poste depuis le portail Office","Prévenir le support, qui vérifiera s'il y a un incident Microsoft","Changer tout de suite ton mot de passe, au cas où il aurait fuité","Supprimer ton profil Outlook, puis en recréer un nouveau"],"g":1,"e":"Quand plusieurs personnes sont touchées en même temps, c'est souvent un incident côté service : le support consulte l'état des services Microsoft 365. Les manipulations lourdes sur ton poste ne régleraient rien."},
  {"theme":"admin","level":"recrue","format":"tf","q":"Un compte utilisateur peut exister dans Microsoft 365 sans avoir de licence attribuée.","a":["Vrai","Faux"],"g":0,"e":"Vrai : le compte (identité) et la licence sont deux choses séparées. Un compte sans licence peut se connecter mais n'a accès ni à Outlook, ni à Teams, ni aux autres services sous licence."},
  {"theme":"admin","level":"recrue","format":"input","q":"Comment s'appelle le rôle d'administration qui a tous les droits sur le tenant ? (Administrateur …)","placeholder":"global","answers":["global","général","general","administrateur global","administrateur général","admin global","admin général","global administrator","global admin"],"e":"L'Administrateur général (ou global, Global Administrator) peut tout faire dans le tenant. C'est pour ça qu'on limite le nombre de personnes qui l'ont et qu'on préfère des rôles plus ciblés au quotidien."},
  {"theme":"admin","level":"recrue","format":"order","q":"Tu débutes au support : remets dans l'ordre la prise en charge d'un signalement « Teams ne marche pas » :","items":["Recueillir les infos : message d'erreur, utilisateurs touchés, heure","Vérifier l'état des services Microsoft 365","Appliquer la correction ou escalader au niveau supérieur","Informer l'utilisateur et clôturer le ticket"],"e":"On commence par comprendre le problème, puis on écarte une panne Microsoft avant de chercher côté utilisateur. On ne clôture qu'après avoir prévenu l'utilisateur."},
  {"theme":"admin","level":"recrue","format":"single","q":"Dans l'adresse ines.martin@contoso.fr, que représente « contoso.fr » ?","a":["Le nom du serveur de ton PC","Le nom de ton équipe Teams","Le nom de domaine de l'organisation","Ton identifiant de licence"],"g":2,"e":"Le domaine identifie l'organisation. L'entreprise l'ajoute et le vérifie dans le centre d'admin (Paramètres > Domaines) pour l'utiliser dans les adresses et identifiants."},
  {"theme":"admin","level":"hero","format":"single","q":"Que désigne le domaine « contoso.onmicrosoft.com » d'un tenant ?","a":["Le domaine initial du tenant, créé d'office et impossible à supprimer","Un domaine de test temporaire, à supprimer dès la mise en service","Le domaine réservé aux comptes invités venus d'autres organisations","Un domaine que l'entreprise a acheté chez un registrar comme OVH"],"g":0,"e":"Le domaine onmicrosoft.com est fourni à la création du tenant et reste toujours présent, même après l'ajout d'un domaine personnalisé. On peut par contre choisir un autre domaine par défaut."},
  {"theme":"admin","level":"hero","format":"tf","q":"Retirer la licence d'un utilisateur supprime immédiatement et définitivement sa boîte aux lettres.","a":["Vrai","Faux"],"g":1,"e":"Faux : après le retrait de la licence, les données de la boîte aux lettres sont conservées pendant une période de grâce de 30 jours avant suppression. Réattribuer la licence à temps permet de tout retrouver."},
  {"theme":"admin","level":"hero","format":"single","q":"Un utilisateur a bien une licence Microsoft 365 E3, mais Teams ne s'ouvre pas pour lui. Cause possible côté admin ?","a":["Le rôle Administrateur Teams ne lui a pas été attribué","Il n'est encore membre d'aucune équipe dans Teams","L'application Teams a été décochée dans les options de sa licence","Sa stratégie de réunion Teams interdit l'enregistrement"],"g":2,"e":"Dans la fiche utilisateur (Licences et applications), l'admin peut désactiver certaines applications incluses dans une licence : vérifie ces cases avant de chercher plus loin. Vérifie aussi la licence exacte : Microsoft vend Microsoft 365 E3 avec Teams et une version « E3 (no Teams) », qui demande une licence Teams Enterprise à part. Aucun rôle d'admin ni aucune équipe ne sont nécessaires pour ouvrir Teams."},
  {"theme":"admin","level":"hero","format":"multi","q":"Depuis la fiche d'un utilisateur dans le centre d'admin Microsoft 365, que peut faire un admin ? (plusieurs réponses)","a":["Réinitialiser son mot de passe","Gérer ses licences et applications","Lire directement le contenu de ses e-mails","Bloquer sa connexion"],"g":[0,1,3],"e":"La fiche utilisateur permet de gérer compte, mot de passe, licences et connexion. Lire les e-mails de quelqu'un demande une délégation d'accès explicite (et un cadre légal), pas un simple clic."},
  {"theme":"admin","level":"hero","format":"input","q":"Dans le centre d'admin, quel menu sous « Facturation » liste les abonnements achetés par l'organisation ?","placeholder":"Facturation > …","answers":["Vos produits","Your products"],"e":"Facturation > Vos produits affiche chaque abonnement, sa quantité de licences et ses options. Les licences attribuées se suivent aussi dans Facturation > Licences."},
  {"theme":"admin","level":"hero","format":"single","q":"Un collaborateur est suspendu temporairement. Comment l'empêcher de se connecter sans supprimer son compte ?","a":["Retirer toutes ses licences suffit à bloquer la connexion","Utiliser l'option « Bloquer la connexion » sur son compte","Renommer son adresse e-mail","Supprimer son compte puis le restaurer plus tard"],"g":1,"e":"« Bloquer la connexion » empêche toute nouvelle authentification tout en conservant compte, licences et données. Retirer les licences ne bloque pas la connexion et lance le compte à rebours de suppression des données."},
  {"theme":"admin","level":"hero","format":"single","q":"Un problème nécessite l'aide de Microsoft. Comment l'admin ouvre-t-il une demande de support ?","a":["En publiant un message dans le Centre de messages du centre d'admin","En ajoutant un commentaire sur la feuille de route Microsoft 365","En appelant le numéro de support affiché dans l'aide d'Outlook","Via « Aide et support » dans le centre d'administration Microsoft 365"],"g":3,"e":"Le bouton Aide et support du centre d'admin propose d'abord des solutions, puis permet de créer une demande de service. Le Centre de messages et la feuille de route sont en lecture seule."},
  {"theme":"admin","level":"super","format":"single","q":"Lors de l'ajout d'un domaine personnalisé, comment prouves-tu à Microsoft que tu en es propriétaire ?","a":["En envoyant au support une facture du registrar à ton nom","En ajoutant dans la zone DNS l'enregistrement TXT fourni par Microsoft","En créant une boîte admin@ sur le domaine pour recevoir un code","En important le certificat SSL du domaine dans le centre d'admin"],"g":1,"e":"Microsoft fournit une valeur à publier (généralement un TXT, parfois un MX) dans le DNS du domaine, puis vérifie sa présence. Ensuite seulement, tu configures les enregistrements des services."},
  {"theme":"admin","level":"super","format":"order","q":"Remets dans l'ordre l'ajout d'un domaine personnalisé dans Microsoft 365 :","items":["Paramètres > Domaines > Ajouter un domaine, puis saisir le nom","Publier l'enregistrement TXT et lancer la vérification","Créer les enregistrements DNS des services (MX, CNAME autodiscover, SPF…)","Mettre à jour les identifiants (UPN) et adresses des utilisateurs"],"e":"On ajoute et vérifie le domaine, puis on crée les enregistrements qui font fonctionner la messagerie et les clients. Les utilisateurs ne basculent sur le nouveau domaine qu'une fois tout en place."},
  {"theme":"admin","level":"super","format":"tf","q":"Le Centre de messages peut envoyer aux admins un résumé hebdomadaire par e-mail de ses publications.","a":["Vrai","Faux"],"g":0,"e":"Vrai : dans les préférences du Centre de messages (onglet E-mail), on peut activer le résumé hebdomadaire et des e-mails pour les mises à jour majeures, y compris vers d'autres adresses que la sienne."},
  {"theme":"admin","level":"super","format":"single","q":"Dans les rapports d'utilisation, les noms des utilisateurs apparaissent sous forme d'identifiants illisibles. Pourquoi ?","a":["Les rapports sont corrompus et doivent être régénérés depuis le centre d'admin","Seul l'Administrateur global voit les vrais noms, pas le Lecteur de rapports","Il faut une licence E5 ou Power BI Pro pour afficher les noms","Le masquage des noms, activé par défaut dans les paramètres Rapports"],"g":3,"e":"Par défaut, Microsoft masque les noms d'utilisateurs, de groupes et de sites dans les rapports pour la confidentialité. Un admin habilité peut désactiver ce masquage dans Paramètres > Paramètres de l'organisation > Services > Rapports."},
  {"theme":"admin","level":"legende","format":"input","q":"Quelle cmdlet Microsoft Graph PowerShell attribue ou retire des licences à un utilisateur ?","placeholder":"Verbe-Nom…","answers":["Set-MgUserLicense"],"e":"Set-MgUserLicense prend les paramètres -AddLicenses et -RemoveLicenses. Elle remplace Set-MsolUserLicense (MSOnline) et Set-AzureADUserLicense (AzureAD)."},
  {"theme":"admin","level":"legende","format":"single","q":"Set-MgUserLicense échoue sur un compte tout juste créé par script. Quelle propriété manque le plus souvent ?","a":["UsageLocation","Department","OnPremisesImmutableId","PreferredLanguage"],"g":0,"e":"Une licence ne peut pas être attribuée à un utilisateur sans emplacement d'utilisation (UsageLocation, code pays comme FR), car la disponibilité des services dépend du pays. Le centre d'admin le demande d'office, pas un script."},
  {"theme":"admin","level":"legende","format":"single","q":"Quelle cmdlet liste les SKU du tenant avec les unités activées et consommées (ConsumedUnits) ?","a":["Get-MgUserLicenseDetail","Get-MsolAccountSku","Get-MgSubscribedSku","Get-MgOrganization"],"g":2,"e":"Get-MgSubscribedSku renvoie SkuPartNumber, SkuId, ConsumedUnits et PrepaidUnits. Get-MgUserLicenseDetail travaille par utilisateur, et Get-MsolAccountSku vient du module MSOnline retiré."},
  {"theme":"admin","level":"legende","format":"tf","q":"En 2026, les modules MSOnline et AzureAD restent la méthode recommandée pour gérer les licences par script.","a":["Vrai","Faux"],"g":1,"e":"Faux : MSOnline a cessé de fonctionner en 2025, et AzureAD a été retiré à son tour à partir de fin 2025. Microsoft recommande Microsoft Graph PowerShell (Get-MgSubscribedSku, Set-MgUserLicense), Microsoft Entra PowerShell ou l'API Graph.","maj":{"date":"2025-05-30","texte":"Microsoft retire le module PowerShell MSOnline ; AzureAD, déprécié, n'est plus supporté non plus.","source":"Microsoft Learn","url":"https://learn.microsoft.com/powershell/azure/active-directory/migration-faq","avant":[0]}},
  {"theme":"admin","level":"legende","format":"multi","q":"Quelles affirmations sur l'attribution de licences par groupe sont exactes ? (plusieurs réponses)","a":["Un utilisateur peut hériter de licences de plusieurs groupes à la fois","Les membres d'un groupe imbriqué n'héritent pas de la licence du groupe parent","Elle fonctionne avec des groupes dynamiques","Une licence héritée d'un groupe peut être retirée directement sur la fiche de l'utilisateur"],"g":[0,1,2],"e":"Un utilisateur peut être membre de plusieurs groupes porteurs de licences, seuls les membres directs d'un groupe reçoivent sa licence, et les groupes dynamiques sont pris en charge. Une licence héritée ne se retire pas sur l'utilisateur : il faut le sortir du groupe ou modifier la licence du groupe."},
  {"theme":"admin","level":"legende","format":"single","q":"Quel rôle peut lire l'état des services et le Centre de messages et ouvrir des demandes de support Microsoft, sans gérer utilisateurs ni licences ?","a":["Administrateur du support technique","Administrateur du support de service","Lecteur du Centre de messages","Administrateur des utilisateurs"],"g":1,"e":"L'Administrateur du support de service est fait pour ça. L'Administrateur du support technique (Helpdesk) peut aussi ouvrir des demandes, mais il réinitialise les mots de passe d'utilisateurs ; le Lecteur du Centre de messages ne voit que les publications du Centre de messages."},
  {"theme":"admin","level":"legende","format":"single","q":"Quel rôle peut attribuer n'importe quel rôle Microsoft Entra, y compris Administrateur global, sans être lui-même Administrateur global ?","a":["Administrateur des utilisateurs","Administrateur de la sécurité","Administrateur d'authentification privilégié","Administrateur de rôle privilégié"],"g":3,"e":"L'Administrateur de rôle privilégié gère les attributions de rôles et PIM : c'est un rôle aussi sensible que l'Administrateur global. L'Administrateur d'authentification privilégié gère les méthodes d'authentification, pas les rôles."},
  {"theme":"admin","level":"legende","format":"order","q":"Remets dans l'ordre la migration de licences attribuées directement vers une attribution par groupe :","items":["Créer ou choisir le groupe cible (statique ou dynamique)","Attribuer la licence au groupe","Vérifier que les licences héritées sont actives et sans erreur","Retirer les licences attribuées directement aux utilisateurs"],"e":"On retire les attributions directes en dernier : un utilisateur qui a la même licence en direct et par groupe n'en consomme qu'une, donc aucune coupure de service pendant la bascule."},
  {"theme":"admin","level":"legende","format":"single","q":"Attribution par groupe : un membre est en erreur « Plans de service en conflit ». Que se passe-t-il ?","a":["Le groupe dépasse la limite de membres pour l'attribution par groupe","Il n'y a plus assez de licences disponibles dans l'abonnement","Une de ses licences contient un plan incompatible avec celle du groupe","Son emplacement d'utilisation diffère du pays du tenant"],"g":2,"e":"Certains plans s'excluent mutuellement (deux variantes d'un même service, par exemple). Il faut retirer la licence directe en conflit ou désactiver le plan concerné. Le manque de licences provoque une autre erreur."},
  {"theme":"admin","level":"legende","format":"single","q":"Avec Set-MgUserLicense, comment attribuer une licence en désactivant un de ses plans de service ?","a":["-AddLicenses @{SkuId=$sku; DisabledPlans=@($planId)} -RemoveLicenses @()","-AddLicenses $sku -DisabledPlans $planId","-SkuId $sku -ExcludePlans $planId","-AddLicenses @{SkuId=$sku} -RemoveServicePlans @($planId)"],"g":0,"e":"Les plans désactivés se passent dans la table de hachage d'AddLicenses (DisabledPlans, avec les GUID des plans). -RemoveLicenses est obligatoire, même vide. Les autres paramètres n'existent pas."},
  {"theme":"entra","level":"recrue","format":"single","q":"Quelle adresse ouvre le portail « Mon compte », où tu gères toi-même ton compte professionnel ?","a":["portal.azure.com","admin.microsoft.com","myaccount.microsoft.com","myapps.microsoft.com"],"g":2,"e":"myaccount.microsoft.com est le portail Mon compte de l'utilisateur : informations de sécurité, mot de passe, appareils, activité récente. admin.microsoft.com et portal.azure.com sont réservés aux administrateurs."},
  {"theme":"entra","level":"recrue","format":"single","q":"Le portail « Mes applications » (myapps.microsoft.com) sert à…","a":["installer la suite Office sur ton PC personnel ou pro","retrouver et lancer les applis pro auxquelles tu as accès","acheter des applis validées dans le Microsoft Store","gérer les licences et les accès de ton équipe"],"g":1,"e":"Mes applications regroupe les applications professionnelles publiées pour toi (Microsoft 365 et applications tierces connectées à Entra ID), souvent avec l'authentification unique."},
  {"theme":"entra","level":"recrue","format":"tf","q":"Tu reçois une demande d'approbation dans Microsoft Authenticator alors que tu n'essaies pas de te connecter : tu dois l'approuver pour la faire disparaître.","a":["Vrai","Faux"],"g":1,"e":"Faux : une demande que tu n'as pas déclenchée signifie que quelqu'un connaît peut-être ton mot de passe. Refuse-la, change ton mot de passe et préviens le support ou la sécurité."},
  {"theme":"entra","level":"recrue","format":"order","q":"Remets dans l'ordre l'ajout de Microsoft Authenticator comme méthode de connexion :","items":["Ouvrir la page « Informations de sécurité » dans Mon compte","Cliquer sur « Ajouter une méthode de connexion » et choisir Microsoft Authenticator","Dans l'application, ajouter un compte professionnel ou scolaire","Scanner le QR code affiché à l'écran","Approuver la notification de test envoyée sur le téléphone"],"e":"On démarre depuis Informations de sécurité, l'assistant affiche un QR code que l'application scanne, puis une notification de test confirme que tout fonctionne."},
  {"theme":"entra","level":"recrue","format":"input","q":"Dans le portail Mon compte, comment s'appelle la page où tu ajoutes ou supprimes tes méthodes de vérification (Authenticator, téléphone…) ?","placeholder":"Nom de la page","answers":["Informations de sécurité","Informations de securite","Security info"],"e":"La page « Informations de sécurité » (Security info) liste tes méthodes de connexion et te permet d'en ajouter, d'en supprimer ou de changer la méthode par défaut."},
  {"theme":"entra","level":"recrue","format":"single","q":"Dans Microsoft Authenticator, le code à 6 chiffres affiché sous ton compte professionnel change…","a":["toutes les 30 secondes","toutes les 5 minutes","toutes les heures","une fois par jour"],"g":0,"e":"C'est un code à usage unique basé sur l'heure (TOTP) renouvelé toutes les 30 secondes : même intercepté, il devient vite inutilisable."},
  {"theme":"entra","level":"recrue","format":"single","q":"Pourquoi ton entreprise t'impose-t-elle l'authentification multifacteur (MFA) ?","a":["Pour te connecter plus vite grâce à la notification sur ton téléphone","Pour pouvoir se passer de mot de passe sur tous les sites","Pour vérifier que tu es bien réveillé avant 9 h","Pour qu'un pirate qui a ton mot de passe ne puisse pas entrer"],"g":3,"e":"La MFA ajoute une preuve que tu possèdes (téléphone, clé de sécurité) ou que tu es (biométrie) : le mot de passe seul ne suffit plus à entrer dans ton compte."},
  {"theme":"entra","level":"recrue","format":"multi","q":"Quelles sont de bonnes pratiques pour ton mot de passe professionnel ? (plusieurs réponses)","a":["Utiliser une longue phrase de passe difficile à deviner","Le noter sur un post-it collé sous le clavier pour ne pas l'oublier","Ne pas réutiliser le même mot de passe sur des sites personnels","Ne jamais le communiquer, même à quelqu'un qui dit appeler du support"],"g":[0,2,3],"e":"Longueur, unicité et confidentialité sont les trois réflexes clés. Le support n'a jamais besoin de ton mot de passe, et un post-it est à la portée de n'importe qui."},
  {"theme":"entra","level":"recrue","format":"single","q":"Tu connais ton mot de passe actuel et tu veux le changer depuis le web. Où vas-tu ?","a":["Dans Outlook, Fichier > Options","Dans Mon compte, via la vignette « Mot de passe »","Dans Teams, Paramètres > Confidentialité","Dans OneDrive, Paramètres > Sauvegarde"],"g":1,"e":"Le portail Mon compte (myaccount.microsoft.com) propose une vignette Mot de passe pour le modifier. Les paramètres d'Outlook, Teams ou OneDrive ne gèrent pas ton mot de passe Entra ID."},
  {"theme":"entra","level":"recrue","format":"tf","q":"Dans Mon compte, la page « Appareils » te permet de voir les appareils liés à ton compte et de désactiver un appareil perdu.","a":["Vrai","Faux"],"g":0,"e":"Vrai : la page Appareils liste les appareils inscrits ou joints avec ton compte et propose de désactiver un appareil perdu ou volé. Préviens aussi ton support pour qu'il prenne les autres mesures."},
  {"theme":"entra","level":"hero","format":"single","q":"Un utilisateur pense que quelqu'un s'est connecté à son compte. Dans Mon compte, où peut-il vérifier ses dernières connexions lui-même ?","a":["Organisations","Activité récente","Paramètres et confidentialité","Abonnements"],"g":1,"e":"La page Activité récente affiche les connexions récentes (lieu, appareil, application) et permet de signaler « Ce n'était pas moi », ce qui guide l'utilisateur vers la sécurisation de son compte."},
  {"theme":"entra","level":"hero","format":"single","q":"Le verrouillage intelligent (smart lockout) d'Entra ID…","a":["désactive le compte dans l'AD local après 5 échecs, jusqu'à l'intervention d'un admin","oblige l'utilisateur à appeler le support pour chaque déverrouillage du compte","verrouille temporairement la connexion après trop d'échecs, sans pénaliser le vrai utilisateur","bloque l'adresse IP de l'attaquant dans le pare-feu réseau de l'entreprise"],"g":2,"e":"Le smart lockout bloque temporairement les tentatives après une série d'échecs et tient compte de la provenance des tentatives pour ne pas pénaliser le vrai utilisateur. Le verrou se lève seul au bout d'un délai."},
  {"theme":"entra","level":"hero","format":"multi","q":"Quelles informations trouves-tu dans le détail d'une connexion des journaux de connexion d'Entra ID ? (plusieurs réponses)","a":["L'adresse IP et l'emplacement approximatif","L'application à laquelle l'utilisateur a tenté d'accéder","Le mot de passe saisi lors d'un échec","Les stratégies d'accès conditionnel appliquées et leur résultat"],"g":[0,1,3],"e":"Le journal indique IP, emplacement, application, appareil, code d'erreur et résultat de l'accès conditionnel. Le mot de passe n'est évidemment jamais journalisé."},
  {"theme":"entra","level":"hero","format":"tf","q":"Il est recommandé qu'un utilisateur enregistre plusieurs méthodes de vérification, pour ne pas être bloqué s'il perd l'une d'elles.","a":["Vrai","Faux"],"g":0,"e":"Vrai : avec une seule méthode, un téléphone perdu ou changé bloque l'utilisateur. Une deuxième méthode (autre appareil, clé de sécurité, téléphone) évite un appel au support."},
  {"theme":"entra","level":"hero","format":"order","q":"Remets dans l'ordre une réinitialisation de mot de passe en libre-service (SSPR) :","items":["Cliquer sur « Mot de passe oublié ? » sur la page de connexion","Saisir son identifiant et recopier les caractères de vérification","Prouver son identité avec la ou les méthodes demandées","Choisir un nouveau mot de passe","Se reconnecter avec le nouveau mot de passe"],"e":"Le SSPR vérifie d'abord le compte, puis l'identité via les méthodes enregistrées (Authenticator, SMS, e-mail…), et seulement ensuite laisse définir un nouveau mot de passe."},
  {"theme":"entra","level":"hero","format":"input","q":"Quelle adresse courte (aka.ms/…) envoie directement un utilisateur vers la réinitialisation de mot de passe en libre-service ?","placeholder":"aka.ms/…","answers":["aka.ms/sspr","https://aka.ms/sspr","sspr"],"e":"aka.ms/sspr mène à la page de réinitialisation de mot de passe en libre-service d'Entra ID : pratique à donner à un utilisateur bloqué."},
  {"theme":"entra","level":"hero","format":"single","q":"L'« inscription combinée des informations de sécurité » dans Entra ID permet…","a":["de fusionner deux comptes utilisateurs en un seul compte Entra","d'enregistrer en une fois ses méthodes MFA et de réinitialisation","de partager une même méthode MFA entre collègues","de synchroniser les mots de passe avec l'Active Directory local"],"g":1,"e":"Avec l'inscription combinée, l'utilisateur déclare ses méthodes une seule fois (page Informations de sécurité) et elles servent à la fois à la MFA et au SSPR."},
  {"theme":"entra","level":"hero","format":"single","q":"Un utilisateur voit une fenêtre « Autorisations demandées » : une application tierce inconnue veut lire ses mails et ses fichiers. Que lui conseilles-tu ?","a":["Accepter : Microsoft a forcément vérifié l'application","Accepter puis supprimer l'application plus tard","Refuser en cas de doute et signaler la demande au support","Accepter, car la MFA protège déjà ses données"],"g":2,"e":"C'est un scénario classique d'hameçonnage par consentement : une fois accepté, l'application accède aux données sans mot de passe, et la MFA ne l'arrête pas. On refuse et on fait vérifier."},
  {"theme":"entra","level":"super","format":"single","q":"Tu veux empêcher les utilisateurs d'accorder eux-mêmes des autorisations à des applications tierces. Où le règles-tu dans le centre d'administration Microsoft Entra ?","a":["Utilisateurs > Paramètres utilisateur > Les utilisateurs peuvent inscrire des applications","Protection > Méthodes d'authentification > Stratégies > Paramètres d'inscription","Applications d'entreprise > Consentement et autorisations > Paramètres de consentement de l'utilisateur","Identité > Applications > Inscriptions d'applications > Autorisations de l'API"],"g":2,"e":"Les paramètres de consentement de l'utilisateur se trouvent sous Applications d'entreprise > Consentement et autorisations. On peut y interdire le consentement ou le limiter aux éditeurs vérifiés, et activer le flux de demande de consentement administrateur. Le réglage « Les utilisateurs peuvent inscrire des applications » concerne la création d'applications, pas le consentement."},
  {"theme":"entra","level":"super","format":"input","q":"Quelle cmdlet du module Microsoft Graph PowerShell ouvre la connexion au tenant, avec par exemple -Scopes \"User.Read.All\" ?","placeholder":"Verbe-Nom","answers":["Connect-MgGraph"],"e":"Connect-MgGraph établit la session Microsoft Graph PowerShell ; le paramètre -Scopes précise les autorisations demandées. Connect-AzureAD et Connect-MsolService appartiennent à des modules retirés."},
  {"theme":"entra","level":"super","format":"multi","q":"Un compte utilisateur est compromis. Quelles actions dans Entra ID sont pertinentes ? (plusieurs réponses)","a":["Réinitialiser son mot de passe","Révoquer ses sessions pour invalider les jetons actifs","Le retirer manuellement de ses groupes dynamiques","Bloquer sa connexion le temps de l'analyse"],"g":[0,1,3],"e":"Réinitialiser, révoquer les sessions et bloquer la connexion coupent l'accès de l'attaquant. On ne peut pas retirer manuellement un membre d'un groupe dynamique : c'est la règle d'appartenance qui décide."},
  {"theme":"entra","level":"super","format":"tf","q":"Créer des stratégies d'accès conditionnel nécessite une licence Microsoft Entra ID P1 (incluse par exemple dans Microsoft 365 E3 ou Business Premium) ou supérieure.","a":["Vrai","Faux"],"g":0,"e":"Vrai : l'accès conditionnel est une fonctionnalité Entra ID P1. Les tenants sans P1 s'appuient sur les paramètres de sécurité par défaut."},
  {"theme":"entra","level":"super","format":"order","q":"Remets dans l'ordre la création d'une stratégie d'accès conditionnel exigeant la MFA :","items":["Ouvrir Accès conditionnel dans le centre d'administration Microsoft Entra et créer une nouvelle stratégie","Choisir les utilisateurs ou groupes ciblés, en excluant les comptes d'urgence","Sélectionner les ressources cibles (applications cloud)","Dans Accorder, cocher « Exiger l'authentification multifacteur »","Régler « Activer la stratégie » sur Rapport uniquement, puis créer"],"e":"On définit d'abord les affectations (qui, quelles ressources), puis le contrôle d'accès, et on démarre en Rapport uniquement pour mesurer l'impact avant d'activer. Exclure les comptes break-glass évite de se verrouiller dehors."},
  {"theme":"entra","level":"super","format":"single","q":"Tu veux que seuls certains rôles puissent inviter des utilisateurs externes (B2B). Où se trouve ce réglage ?","a":["Identités externes > Paramètres de collaboration externe","Utilisateurs > Tous les utilisateurs > Inviter un utilisateur externe","Applications d'entreprise > Propriétés","Rôles et administrateurs > Invité"],"g":0,"e":"Les paramètres de collaboration externe (Identités externes) définissent qui peut inviter, les restrictions d'accès des invités et les domaines autorisés ou bloqués. Le bouton Inviter ne fait qu'utiliser ces règles."},
  {"theme":"entra","level":"legende","format":"single","q":"Sur un gros tenant, Get-MgUser ne renvoie qu'une partie des utilisateurs. Quel paramètre ajoutes-tu pour tous les récupérer ?","a":["-ResultSize Unlimited","-All","-Top 0","-Filter \"*\""],"g":1,"e":"Les cmdlets Microsoft Graph renvoient une seule page de résultats par défaut ; -All suit la pagination jusqu'au bout. -ResultSize Unlimited est un paramètre des cmdlets Exchange Online, pas de Graph."},
  {"theme":"entra","level":"legende","format":"single","q":"L'évaluation continue de l'accès (Continuous Access Evaluation, CAE) permet…","a":["de renouveler automatiquement les jetons d'accès toutes les heures pour tous les services","de réévaluer toutes les stratégies d'accès conditionnel une fois par nuit, sur chaque session","de mesurer en continu le risque de connexion (IP suspecte, trajet impossible…) avec ID Protection","de révoquer un jeton encore valide dès un événement critique (compte désactivé, mot de passe changé…)"],"g":3,"e":"Avec CAE, les services compatibles (Exchange Online, SharePoint, Teams…) sont informés d'événements critiques et peuvent rejeter un jeton encore valide, au lieu d'attendre son expiration naturelle."},
  {"theme":"entra","level":"legende","format":"tf","q":"Dans une stratégie d'accès conditionnel, un utilisateur à la fois inclus (via un groupe) et exclu (via un autre groupe) n'est pas concerné par la stratégie.","a":["Vrai","Faux"],"g":0,"e":"Vrai : les exclusions l'emportent toujours sur les inclusions. C'est ce qui permet d'exclure proprement les comptes d'urgence de toutes les stratégies."},
  {"theme":"entra","level":"legende","format":"multi","q":"Quelles exigences peux-tu imposer à l'activation d'un rôle éligible dans Privileged Identity Management ? (plusieurs réponses)","a":["Une authentification multifacteur à l'activation","Une justification saisie par l'utilisateur","L'approbation d'un ou plusieurs approbateurs désignés","Une activation possible uniquement via le module PowerShell MSOnline"],"g":[0,1,2],"e":"Les paramètres de rôle PIM permettent d'exiger MFA (ou un contexte d'authentification), justification, informations de ticket et approbation, avec une durée maximale d'activation. MSOnline est un module retiré, sans lien avec PIM."},
  {"theme":"entra","level":"legende","format":"single","q":"Dans l'accès conditionnel, le contrôle « Exiger la force d'authentification » sert à…","a":["exiger un mot de passe plus long que la stratégie de mot de passe par défaut","limiter les méthodes admises, par exemple à une MFA résistante au hameçonnage","calculer le niveau de risque de l'utilisateur à chaque connexion","imposer une fréquence de reconnexion précise pour chaque application"],"g":1,"e":"La force d'authentification va plus loin que « Exiger la MFA » : elle restreint les méthodes admises (MFA résistante au hameçonnage, clés FIDO2, Windows Hello Entreprise…). Le risque relève d'Entra ID Protection, la fréquence des contrôles de session."},
  {"theme":"entra","level":"legende","format":"input","q":"Quelle cmdlet Microsoft Graph PowerShell révoque toutes les sessions de connexion d'un utilisateur (jetons d'actualisation) ?","placeholder":"Verbe-Nom","answers":["Revoke-MgUserSignInSession"],"e":"Revoke-MgUserSignInSession -UserId invalide les jetons d'actualisation de l'utilisateur, qui doit se réauthentifier. C'est l'équivalent de « Révoquer les sessions » dans le centre d'administration."},
  {"theme":"intune","level":"recrue","format":"single","q":"Le Portail d'entreprise indique que ton téléphone est « non conforme ». Quelle est la cause la plus probable ?","a":["Ton forfait mobile n'est pas un forfait pro","Ton téléphone est connecté au Wi-Fi de ta box perso","Ton téléphone n'a pas le code de verrouillage exigé","Tu as installé trop d'applications personnelles"],"g":2,"e":"La conformité vérifie des règles de sécurité fixées par l'entreprise : code de verrouillage, version du système, chiffrement… Le forfait ou le réseau Wi-Fi utilisé n'entrent pas en jeu."},
  {"theme":"intune","level":"recrue","format":"single","q":"Tu as perdu ton téléphone sur lequel tu consultes tes mails pro. Quel est le bon réflexe ?","a":["Prévenir tout de suite le support informatique","Attendre quelques jours qu'il réapparaisse","Changer ton fond d'écran Teams pour passer inaperçu","Désinstaller Outlook de ton PC pour couper l'accès"],"g":0,"e":"Plus le support est prévenu tôt, plus vite il peut verrouiller l'appareil ou effacer les données de l'entreprise à distance avec Intune."},
  {"theme":"intune","level":"recrue","format":"tf","q":"Si ton appareil est non conforme, l'entreprise peut te bloquer l'accès à ta messagerie professionnelle tant que le problème n'est pas corrigé.","a":["Vrai","Faux"],"g":0,"e":"Grâce à l'accès conditionnel, l'entreprise peut exiger un appareil conforme pour accéder à Outlook, Teams ou SharePoint. Une fois le problème corrigé, l'accès revient."},
  {"theme":"intune","level":"recrue","format":"single","q":"« Inscrire » son appareil dans Intune, ça veut dire…","a":["Le faire réparer gratuitement par le service informatique","Le déclarer à l'entreprise pour qu'elle puisse le gérer","Enregistrer sa garantie auprès du fabricant via l'entreprise","Le connecter au Wi-Fi de l'entreprise avec ton compte pro"],"g":1,"e":"L'inscription relie l'appareil à Intune : l'entreprise peut alors lui appliquer des règles de sécurité et lui fournir les applis professionnelles."},
  {"theme":"intune","level":"recrue","format":"multi","q":"Quels éléments peuvent rendre ton téléphone non conforme ? (plusieurs réponses)","a":["Un système (Android ou iOS) trop ancien, pas mis à jour","Un fond d'écran avec une photo de ton chat","Aucun code de verrouillage configuré","Un téléphone « jailbreaké » ou « rooté »"],"g":[0,2,3],"e":"Les règles de conformité portent sur la sécurité : version du système, code de verrouillage, appareil débridé… La personnalisation de l'écran n'a aucun impact."},
  {"theme":"intune","level":"recrue","format":"single","q":"Tu viens d'ajouter un code de verrouillage sur ton téléphone, mais le Portail d'entreprise affiche toujours « non conforme ». Que fais-tu ?","a":["Tu désinstalles le Portail d'entreprise","Tu réinitialises ton téléphone aux paramètres d'usine","Tu changes le mot de passe de ton compte professionnel","Tu relances la vérification depuis le Portail d'entreprise"],"g":3,"e":"L'état de conformité n'est pas mis à jour instantanément : relancer la vérification depuis le Portail d'entreprise force une nouvelle évaluation. Réinitialiser le téléphone est inutile."},
  {"theme":"intune","level":"recrue","format":"single","q":"Que signifie le sigle « MDM » qu'on croise souvent avec Intune ?","a":["Mobile Device Management (gestion des appareils mobiles)","Microsoft Data Monitoring (surveillance des données)","Multi-Device Messaging (messagerie multi-appareils)","Managed Domain Membership (appartenance au domaine)"],"g":0,"e":"MDM = Mobile Device Management : la gestion des appareils (PC, téléphones, tablettes) par l'organisation. Intune est la solution MDM de Microsoft."},
  {"theme":"intune","level":"recrue","format":"order","q":"Remets dans l'ordre l'inscription de ton téléphone Android personnel :","items":["Installer l'application Portail d'entreprise depuis le Google Play Store","Te connecter avec ton compte professionnel","Suivre l'assistant qui crée le profil professionnel","Attendre que la conformité de l'appareil soit vérifiée","Utiliser tes applis pro dans le profil professionnel"],"e":"On installe d'abord le Portail d'entreprise, on s'identifie avec son compte pro, puis l'assistant crée un espace séparé (profil professionnel). Une fois l'appareil jugé conforme, les applis pro sont utilisables."},
  {"theme":"intune","level":"recrue","format":"input","q":"Quel est le nom de l'application Microsoft à installer pour inscrire ton téléphone dans Intune ?","placeholder":"Nom de l'application","answers":["Portail d'entreprise","Company Portal","Portail d entreprise","Intune Portail d'entreprise","Intune Company Portal"],"e":"Le Portail d'entreprise (Company Portal) sert à inscrire l'appareil, vérifier sa conformité et installer les applis mises à disposition par l'entreprise."},
  {"theme":"intune","level":"recrue","format":"tf","q":"Sur un téléphone Android personnel avec un profil professionnel, les applis pro se reconnaissent à la petite mallette affichée sur leur icône.","a":["Vrai","Faux"],"g":0,"e":"Le profil professionnel Android sépare les applis pro des applis perso ; les applis pro portent un badge en forme de mallette."},
  {"theme":"intune","level":"recrue","format":"single","q":"Tu essaies de copier un passage d'un mail Outlook pro pour le coller dans ton appli de notes personnelle, et c'est refusé. Pourquoi ?","a":["Le presse-papiers de ton téléphone est saturé et doit être vidé","Une stratégie de protection des applications (Intune) l'interdit","Outlook mobile désactive le copier-coller dans tous les mails","Ton appli de notes refuse le texte mis en forme"],"g":1,"e":"Les stratégies de protection des applications (MAM) d'Intune peuvent bloquer le copier-coller des données pro vers des applis non gérées, pour éviter les fuites."},
  {"theme":"intune","level":"hero","format":"single","q":"Un utilisateur ne trouve pas une application dans son Portail d'entreprise alors que ses collègues la voient. Cause la plus probable ?","a":["Son compte n'a pas le rôle Administrateur Intune requis","Il doit d'abord la télécharger depuis le site de l'éditeur","L'appli n'est pas affectée en « Disponible » à l'un de ses groupes","Le Portail d'entreprise n'affiche que les applis Microsoft"],"g":2,"e":"Une appli n'apparaît dans le Portail d'entreprise que si elle est affectée (en Disponible ou Requis) à un groupe incluant l'utilisateur ou son appareil. On vérifie donc l'appartenance aux groupes."},
  {"theme":"intune","level":"hero","format":"tf","q":"Une application affectée en « Requis » dans Intune s'installe automatiquement sur l'appareil, sans que l'utilisateur ait besoin de passer par le Portail d'entreprise.","a":["Vrai","Faux"],"g":0,"e":"« Requis » force l'installation ; « Disponible pour les appareils inscrits » laisse l'utilisateur l'installer à la demande depuis le Portail d'entreprise."},
  {"theme":"intune","level":"hero","format":"single","q":"Sur un PC Windows géré, où l'utilisateur peut-il forcer lui-même une synchronisation avec Intune ?","a":["Panneau de configuration > Centre de synchronisation > Synchroniser","Paramètres > Comptes > Accès professionnel ou scolaire > compte > Infos > Synchroniser","Paramètres > Windows Update > Options avancées > Synchroniser les stratégies","Paramètres > Comptes > Synchroniser vos paramètres > Synchroniser maintenant"],"g":1,"e":"Dans Accès professionnel ou scolaire, le bouton Synchroniser (via Infos) déclenche une vérification immédiate des stratégies et applis. Côté admin, l'action « Synchroniser » existe aussi dans le centre d'administration Intune."},
  {"theme":"intune","level":"hero","format":"multi","q":"Quels contrôles peut contenir une stratégie de conformité Intune pour Windows ? (plusieurs réponses)","a":["Une version minimale du système d'exploitation","L'historique de navigation de l'utilisateur","Le chiffrement BitLocker exigé","Un mot de passe exigé pour déverrouiller l'appareil"],"g":[0,2,3],"e":"La conformité vérifie l'état de sécurité de l'appareil (version d'OS, chiffrement, mot de passe…). Intune ne collecte pas l'historique de navigation."},
  {"theme":"intune","level":"hero","format":"order","q":"Remets dans l'ordre le dépannage d'un appareil signalé non conforme :","items":["Ouvrir l'appareil dans le centre d'administration Intune","Consulter son état de conformité par stratégie","Identifier le paramètre en échec","Corriger le problème sur l'appareil","Synchroniser l'appareil et vérifier le nouvel état"],"e":"On part de la fiche de l'appareil, on descend jusqu'au paramètre fautif, on corrige, puis on synchronise pour que la conformité soit réévaluée."},
  {"theme":"intune","level":"hero","format":"input","q":"Quelle est l'adresse web (sans https://) du centre d'administration Microsoft Intune ?","placeholder":"exemple.microsoft.com","answers":["intune.microsoft.com","https://intune.microsoft.com","endpoint.microsoft.com"],"e":"Le centre d'administration Intune est sur intune.microsoft.com ; l'ancienne adresse endpoint.microsoft.com redirige vers lui."},
  {"theme":"intune","level":"hero","format":"single","q":"Dans les « Actions en cas de non-conformité » d'une stratégie, laquelle permet de prévenir l'utilisateur avant qu'il perde l'accès ?","a":["Mettre l'appareil hors service","Réinitialiser l'appareil","Supprimer l'utilisateur de Microsoft Entra ID","Envoyer un e-mail à l'utilisateur final"],"g":3,"e":"« Envoyer un e-mail à l'utilisateur final » utilise un modèle de notification. Combinée à un délai de grâce avant de marquer l'appareil non conforme, elle laisse le temps de corriger."},
  {"theme":"intune","level":"hero","format":"tf","q":"Outlook peut exiger un code PIN à l'ouverture sur un iPhone personnel grâce à une stratégie de protection d'applications, même si ce téléphone n'est pas inscrit dans Intune.","a":["Vrai","Faux"],"g":0,"e":"Les stratégies de protection d'applications (MAM) s'appliquent à l'application et au compte pro, avec ou sans inscription de l'appareil : c'est le scénario classique du BYOD."},
  {"theme":"intune","level":"hero","format":"single","q":"Un utilisateur a égaré son téléphone pro mais pense le retrouver demain au bureau. Quelle action Intune est la plus adaptée pour l'instant ?","a":["Verrouillage à distance","Réinitialisation","Retirer","Supprimer l'appareil d'Intune"],"g":0,"e":"Le verrouillage à distance protège l'appareil sans rien effacer. Réinitialiser ou retirer supprimerait des données, ce qui serait excessif si l'appareil est probablement juste égaré."},
  {"theme":"intune","level":"super","format":"input","q":"Quel script PowerShell (PowerShell Gallery) est couramment utilisé pour récupérer le hachage matériel d'un PC afin de l'enregistrer dans Windows Autopilot ?","placeholder":"Nom du script","answers":["Get-WindowsAutopilotInfo","Get-WindowsAutopilotInfo.ps1","Get-WindowsAutopilotInfoCommunity","Get-WindowsAutopilotInfoCommunity.ps1"],"e":"Get-WindowsAutopilotInfo exporte le hachage matériel dans un CSV à importer dans Intune (ou l'envoie directement avec le paramètre -Online). Une version communautaire maintenue, Get-WindowsAutopilotInfoCommunity, est aussi très utilisée."},
  {"theme":"intune","level":"super","format":"single","q":"À quoi servent les « filtres » d'affectation dans Intune ?","a":["À masquer des stratégies dans le centre d'administration","À affiner une affectation selon les propriétés de l'appareil","À trier les rapports de conformité par date ou par statut","À filtrer les alertes envoyées aux appareils non conformes"],"g":1,"e":"Un filtre s'ajoute à une affectation de groupe pour inclure ou exclure des appareils selon leurs propriétés (modèle, version d'OS, propriété…), par exemple uniquement les appareils d'entreprise ou un modèle précis."},
  {"theme":"intune","level":"super","format":"single","q":"Quel type de profil de configuration Intune permet de rechercher et configurer des milliers de paramètres Windows ou macOS précis par leur nom ?","a":["Modèles d'administration uniquement","Profil personnalisé OMA-URI","Restrictions d'appareil","Catalogue des paramètres"],"g":3,"e":"Le catalogue des paramètres (Settings catalog) liste les paramètres disponibles avec recherche ; c'est le type recommandé. L'OMA-URI reste possible mais oblige à saisir les chemins CSP à la main."},
  {"theme":"intune","level":"super","format":"tf","q":"Une restriction de plateforme d'appareil dans Intune permet de bloquer l'inscription des appareils Android personnels tout en autorisant les appareils Android d'entreprise.","a":["Vrai","Faux"],"g":0,"e":"Les restrictions de plateforme permettent, pour chaque plateforme, d'autoriser ou bloquer l'inscription et de bloquer spécifiquement les appareils personnels."},
  {"theme":"intune","level":"super","format":"multi","q":"Quels éléments sont nécessaires pour l'inscription automatique des PC Windows joints à Microsoft Entra dans Intune ? (plusieurs réponses)","a":["Un serveur WSUS local","Une licence incluant Intune affectée à l'utilisateur","Microsoft Entra ID P1 (ou une offre qui l'inclut)","Une étendue utilisateur MDM incluant l'utilisateur"],"g":[1,2,3],"e":"L'inscription automatique repose sur Entra ID P1, une licence Intune pour l'utilisateur et l'étendue utilisateur MDM (Tous ou un groupe). WSUS n'a rien à voir avec l'inscription."},
  {"theme":"intune","level":"super","format":"order","q":"Remets dans l'ordre la mise en place de l'inscription automatisée des appareils Apple (ADE) :","items":["Configurer le certificat push MDM Apple dans Intune","Télécharger la clé publique depuis Intune et créer le serveur MDM dans Apple Business Manager","Importer dans Intune le jeton obtenu depuis Apple Business Manager","Créer un profil d'inscription ADE","Affecter le profil aux appareils synchronisés"],"e":"Sans certificat push MDM, Intune ne peut gérer aucun appareil Apple. On établit ensuite la relation avec Apple Business Manager via le jeton, puis on crée et affecte le profil d'inscription."},
  {"theme":"intune","level":"legende","format":"single","q":"Les « Correctifs » (Remediations) d'Intune reposent sur…","a":["Deux scripts PowerShell planifiés : un de détection, un de correction","Un seul script PowerShell exécuté au démarrage de l'appareil","Des packages .intunewin redéployés automatiquement à chaque échec","Des stratégies de conformité qui réparent l'appareil non conforme"],"g":0,"e":"Le script de détection signale un problème via son code de sortie ; le script de correction ne s'exécute que dans ce cas. La planification permet de revérifier régulièrement."},
  {"theme":"intune","level":"legende","format":"input","q":"Quelle cmdlet Microsoft Graph PowerShell (v1.0) force la synchronisation d'un appareil géré par Intune ?","placeholder":"Verbe-Nom","answers":["Sync-MgDeviceManagementManagedDevice","Sync-MgBetaDeviceManagementManagedDevice"],"e":"Sync-MgDeviceManagementManagedDevice -ManagedDeviceId <id> envoie l'action de synchronisation, comme le bouton « Synchroniser » du centre d'administration."},
  {"theme":"intune","level":"legende","format":"single","q":"Avec Microsoft Graph PowerShell, quelle cmdlet liste les appareils gérés par Intune (et non les objets appareils de l'annuaire) ?","a":["Get-MgDevice","Get-MgUserOwnedDevice","Get-MgDeviceManagementManagedDevice","Get-MgDirectoryDeviceLocalCredential"],"g":2,"e":"Get-MgDeviceManagementManagedDevice interroge deviceManagement/managedDevices (Intune). Get-MgDevice renvoie les objets appareils Microsoft Entra, qui ne sont pas forcément gérés par Intune."},
  {"theme":"intune","level":"legende","format":"tf","q":"Microsoft recommande de régler le paramètre « Marquer les appareils sans stratégie de conformité affectée comme » sur « Non conforme ».","a":["Vrai","Faux"],"g":0,"e":"Sinon, un appareil sans aucune stratégie affectée est considéré comme conforme et passe l'accès conditionnel. Le passer à Non conforme ferme cette brèche."},
  {"theme":"intune","level":"legende","format":"single","q":"Quelle est la principale différence de la « préparation des appareils Windows Autopilot » (device preparation) par rapport au déploiement Autopilot classique ?","a":["Elle ne fonctionne que pour les appareils joints à un domaine local","Elle exige l'import du hachage matériel via un CSV signé","Elle remplace Intune par Configuration Manager","Elle ne nécessite pas d'enregistrer au préalable le hachage matériel de l'appareil"],"g":3,"e":"Avec la préparation des appareils, l'appareil est ajouté pendant le déploiement à un groupe de sécurité d'appareils défini dans la stratégie, sans enregistrement préalable du hachage matériel."},
  {"theme":"intune","level":"legende","format":"multi","q":"Quelles conditions peut-on configurer dans le « lancement conditionnel » d'une stratégie de protection d'applications ? (plusieurs réponses)","a":["Blocage des appareils jailbreakés ou rootés","Période de grâce hors connexion","Adresse IP publique de l'utilisateur","Version minimale de l'application"],"g":[0,1,3],"e":"Le lancement conditionnel vérifie l'appareil, l'appli et le compte (jailbreak, version d'app ou d'OS, période hors connexion…). La localisation IP relève des emplacements nommés de l'accès conditionnel Entra."},
  {"theme":"intune","level":"legende","format":"single","q":"Dans Intune, où configure-t-on Windows LAPS (mot de passe de l'administrateur local) ?","a":["Profils de configuration > Restrictions d'appareil","Sécurité du point de terminaison > Protection de compte","Conformité > Paramètres de conformité","Applications > Stratégies de configuration d'applications"],"g":1,"e":"Windows LAPS se configure via une stratégie de protection de compte dans Sécurité du point de terminaison ; l'action d'appareil « Faire pivoter le mot de passe de l'administrateur local » permet ensuite une rotation à la demande."},
  {"theme":"intune","level":"legende","format":"single","q":"En cogestion Configuration Manager / Intune, basculer la charge de travail « Stratégies de conformité » sur Intune signifie que…","a":["Configuration Manager et Intune évaluent la conformité en parallèle et on garde le pire résultat","Les appareils sont désinscrits de Configuration Manager","Intune devient l'autorité pour cette charge de travail sur les appareils concernés","Seuls les appareils Windows Server sont évalués par Intune"],"g":2,"e":"Chaque charge de travail peut être laissée à Configuration Manager, basculée en « Pilote Intune » pour un groupe, ou entièrement confiée à Intune, qui en devient alors l'autorité. Le client ConfigMgr reste installé."},
  {"theme":"intune","level":"legende","format":"order","q":"Remets dans l'ordre ce qui se passe pour un appareil qui échoue à une stratégie de conformité avec e-mail immédiat et délai de grâce :","items":["L'appareil s'enregistre et sa conformité est évaluée","Un paramètre est détecté en échec","L'utilisateur reçoit l'e-mail de notification","Le délai de grâce expire et l'appareil est marqué non conforme","L'accès conditionnel bloque l'accès aux ressources"],"e":"Pendant le délai de grâce, l'appareil est « en période de grâce » et reste traité comme conforme par l'accès conditionnel. Le blocage n'intervient qu'une fois l'appareil marqué non conforme."},
  {"theme":"intune","level":"legende","format":"single","q":"À quoi sert la « Page d'état d'inscription » (Enrollment Status Page) lors d'un déploiement Windows ?","a":["À empêcher l'utilisation de l'appareil tant que les applications et stratégies bloquantes ne sont pas installées","À afficher la liste des appareils inscrits de l'utilisateur dans le Portail d'entreprise","À choisir la langue et le clavier pendant l'OOBE","À envoyer un rapport d'inscription par e-mail au responsable"],"g":0,"e":"La Page d'état d'inscription suit l'installation des applis et profils pendant la configuration et peut bloquer l'accès au bureau jusqu'à ce que les éléments requis soient en place."},
  {"theme":"securite365","level":"recrue","format":"single","q":"Tu reçois un mail « de la DSI » qui te demande de confirmer ton mot de passe via un lien. Quel est le bon réflexe dans Outlook ?","a":["Cliquer sur le lien pour vérifier s'il est vrai","Utiliser le bouton « Signaler » puis choisir « Signaler le hameçonnage »","Répondre à l'expéditeur pour lui demander s'il est légitime","Le déplacer simplement dans un dossier « À vérifier »"],"g":1,"e":"Le bouton « Signaler » d'Outlook envoie le message à l'équipe sécurité (et à Microsoft selon la configuration) et le retire de ta boîte. Répondre ou cliquer confirme à l'attaquant que ton adresse est active."},
  {"theme":"securite365","level":"recrue","format":"tf","q":"Quand tu repères un mail d'hameçonnage, le mieux est de le transférer à tous tes collègues pour les prévenir.","a":["Vrai","Faux"],"g":1,"e":"Transférer un mail piégé le propage et risque qu'un collègue clique. On le signale avec le bouton « Signaler » : l'équipe sécurité peut alors le supprimer de toutes les boîtes."},
  {"theme":"securite365","level":"recrue","format":"single","q":"Un client t'assure avoir envoyé un mail, mais il n'est ni dans ta boîte de réception ni dans le courrier indésirable. Où peut-il être ?","a":["Dans le dossier Archive, classé par Outlook","Dans ton calendrier, s'il citait un rendez-vous","En quarantaine, retenu par les filtres de sécurité","Dans tes brouillons, en attente de lecture"],"g":2,"e":"Les messages jugés suspects (spam, hameçonnage, logiciel malveillant) peuvent être placés en quarantaine par Microsoft 365 au lieu d'être livrés. Selon la stratégie de ton entreprise, tu peux les consulter dans le portail de quarantaine ou demander leur libération."},
  {"theme":"securite365","level":"recrue","format":"single","q":"Tu appliques l'étiquette « Confidentiel » à un document Word. Qu'est-ce que ça peut faire, selon la configuration de ton entreprise ?","a":["Le protéger (chiffrement, droits) même s'il sort de l'entreprise","Le supprimer automatiquement au bout de 30 jours sur OneDrive","Empêcher uniquement l'impression, et seulement depuis ton poste","Rien, c'est seulement une couleur affichée dans l'Explorateur"],"g":0,"e":"Une étiquette de confidentialité Microsoft Purview peut ajouter un en-tête ou un filigrane et chiffrer le fichier : la protection voyage avec le document, où qu'il soit copié."},
  {"theme":"securite365","level":"recrue","format":"single","q":"Tu cliques sur un lien dans un mail et une page Microsoft t'indique que le site a été classé comme malveillant. Que s'est-il passé ?","a":["Ton navigateur est mal configuré et bloque tous les liens externes","Le site est en maintenance chez son hébergeur pour quelques heures","Ton compte a été suspendu par l'administrateur après un clic","Les liens fiables (Safe Links) ont bloqué l'adresse au moment du clic"],"g":3,"e":"Defender pour Office 365 vérifie les liens au moment où tu cliques, pas seulement à la réception : un site devenu malveillant après l'envoi est donc bloqué. Ne cherche pas à contourner l'avertissement, préviens plutôt le support."},
  {"theme":"securite365","level":"recrue","format":"multi","q":"Quels indices doivent te faire soupçonner un mail d'hameçonnage ? (plusieurs réponses)","a":["Un ton urgent ou menaçant (« ton compte sera fermé aujourd'hui »)","Une adresse d'expéditeur qui imite un domaine connu avec une lettre changée","Une signature avec le logo officiel de l'entreprise","Un lien dont l'adresse réelle, au survol, ne correspond pas au texte affiché"],"g":[0,1,3],"e":"Urgence, domaine imité et lien trompeur sont des signaux classiques. Un logo, lui, se copie en deux secondes : ce n'est jamais une preuve d'authenticité."},
  {"theme":"securite365","level":"recrue","format":"order","q":"Remets dans l'ordre les étapes pour signaler un mail suspect dans Outlook :","items":["Sélectionner le mail suspect sans cliquer sur ses liens ni ses pièces jointes","Cliquer sur le bouton « Signaler » du ruban","Choisir « Signaler le hameçonnage »","Confirmer l'envoi du signalement"],"e":"Le signalement part vers l'équipe sécurité et le message est retiré de ta boîte. Surtout, n'ouvre ni liens ni pièces jointes avant de signaler."},
  {"theme":"securite365","level":"recrue","format":"input","q":"Quel est le nom du bouton intégré à Outlook qui permet de déclarer un mail comme hameçonnage ou courrier indésirable ?","placeholder":"Nom du bouton","answers":["Signaler","Report","Signaler le message"],"e":"Le bouton « Signaler » est intégré au ruban d'Outlook (nouvel Outlook, Outlook sur le web, Outlook classique). Il remplace les anciens compléments de signalement."},
  {"theme":"securite365","level":"recrue","format":"single","q":"Dans Outlook, tu choisis « Chiffrer » puis « Ne pas transférer » avant d'envoyer un mail. Que peut faire le destinataire ?","a":["Le transférer à qui il veut, mais chiffré","Le lire, mais pas le transférer, l'imprimer ni en copier le contenu","Le lire uniquement pendant 24 heures","Rien, il doit d'abord installer une application spéciale"],"g":1,"e":"L'option « Ne pas transférer » chiffre le message et empêche le destinataire de le transférer, de l'imprimer ou d'en copier le contenu. L'option « Chiffrer » seule protège le message sans ces restrictions."},
  {"theme":"securite365","level":"recrue","format":"tf","q":"Le bandeau « Vous ne recevez pas souvent de courrier de… » en haut d'un mail t'avertit que tu échanges peut-être pour la première fois avec cet expéditeur.","a":["Vrai","Faux"],"g":0,"e":"C'est le conseil de sécurité de premier contact. Il ne dit pas que le mail est dangereux, mais t'invite à vérifier l'expéditeur, notamment en cas de demande inhabituelle."},
  {"theme":"securite365","level":"recrue","format":"single","q":"En rédigeant un mail contenant un numéro de carte bancaire, un bandeau t'avertit que le message contient des informations sensibles. D'où vient ce message ?","a":["De l'Éditeur Microsoft intégré à Outlook","D'une alerte de l'antivirus installé sur ton poste","D'une stratégie DLP définie par ton entreprise","Du filtre anti-spam du serveur du destinataire"],"g":2,"e":"C'est un conseil de stratégie DLP (protection contre la perte de données) de Microsoft Purview : il te prévient avant l'envoi. Selon la configuration, le mail peut être bloqué ou envoyé avec une justification."},
  {"theme":"securite365","level":"recrue","format":"single","q":"Tu reçois un mail dont la pièce jointe est remplacée par un message indiquant qu'elle est en cours d'analyse. Que faut-il faire ?","a":["Patienter : la vraie pièce jointe arrivera si l'analyse la juge sûre","Demander à l'expéditeur de la renvoyer au format ZIP","Transférer le mail vers ta messagerie personnelle pour l'ouvrir","Supprimer le mail, il est forcément dangereux"],"g":0,"e":"C'est la « remise dynamique » des pièces jointes fiables (Safe Attachments) : le corps du mail arrive tout de suite et la pièce jointe est réinsérée une fois l'analyse terminée. Si elle est malveillante, elle ne te sera pas livrée."},
  {"theme":"securite365","level":"hero","format":"single","q":"Un utilisateur veut passer un document de « Confidentiel » à « Général » et Word lui demande une justification. Pourquoi ?","a":["Son abonnement ne lui permet pas de retirer une étiquette appliquée","Le document est en lecture seule dans son espace OneDrive","Word exige une justification à chaque modification du fichier","La stratégie d'étiquettes exige une justification pour abaisser le niveau"],"g":3,"e":"La stratégie de publication des étiquettes peut exiger une justification pour supprimer une étiquette ou la remplacer par une étiquette moins restrictive. Cette action est tracée dans l'audit."},
  {"theme":"securite365","level":"hero","format":"single","q":"Word refuse d'enregistrer un nouveau document tant que l'utilisateur n'a pas choisi d'étiquette de confidentialité. Quel paramètre de stratégie est en cause ?","a":["L'étiquetage automatique côté service","L'étiquetage obligatoire","L'étiquette par défaut","Le chiffrement à double clé"],"g":1,"e":"Avec l'étiquetage obligatoire, l'utilisateur doit choisir une étiquette avant d'enregistrer ou d'envoyer. Une étiquette par défaut, elle, s'appliquerait automatiquement sans rien demander."},
  {"theme":"securite365","level":"hero","format":"tf","q":"Appliquer une étiquette de confidentialité à une équipe Teams (étiquette de conteneur) étiquette automatiquement tous les fichiers stockés dans cette équipe.","a":["Vrai","Faux"],"g":1,"e":"Une étiquette de conteneur contrôle des paramètres du groupe ou du site (confidentialité publique/privée, partage externe, accès depuis des appareils non gérés), mais n'étiquette pas les fichiers qu'il contient."},
  {"theme":"securite365","level":"hero","format":"multi","q":"Où les liens fiables (Safe Links) de Defender pour Office 365 peuvent-ils protéger les clics ? (plusieurs réponses)","a":["Dans les mails reçus dans Outlook","Dans les conversations et canaux Microsoft Teams","Dans les SMS reçus sur un téléphone personnel","Dans les applications Office prises en charge (Word, Excel, PowerPoint…)"],"g":[0,1,3],"e":"Safe Links couvre les mails, Teams et les applications Office prises en charge, selon la stratégie. Les SMS d'un téléphone personnel ne passent pas par Microsoft 365."},
  {"theme":"securite365","level":"hero","format":"order","q":"Remets dans l'ordre le parcours d'un utilisateur qui récupère un mail légitime placé en quarantaine (stratégie autorisant la demande de libération) :","items":["Recevoir la notification de quarantaine ou ouvrir le portail de quarantaine","Repérer le message et vérifier son expéditeur et son objet","Cliquer sur « Demander la libération »","L'administrateur examine et approuve la demande","Le message est livré dans la boîte de réception"],"e":"Selon la stratégie de quarantaine, l'utilisateur peut libérer lui-même le message ou seulement en demander la libération ; dans ce second cas, un administrateur valide avant la livraison."},
  {"theme":"securite365","level":"hero","format":"input","q":"À quelle adresse un utilisateur peut-il consulter ses messages mis en quarantaine par Microsoft 365 ?","placeholder":"https://…","answers":["https://security.microsoft.com/quarantine","security.microsoft.com/quarantine","https://security.microsoft.com/quarantine/"],"e":"La page Quarantaine du portail Microsoft Defender affiche aux utilisateurs leurs propres messages retenus ; ils ne voient pas ceux des autres."},
  {"theme":"securite365","level":"hero","format":"single","q":"Un utilisateur voit en quarantaine un mail classé « logiciel malveillant » mais ne peut ni le libérer ni en demander la libération. Pourquoi ?","a":["Sa boîte aux lettres est pleine et ne peut plus recevoir ce message","Il doit d'abord signaler le mail comme « non indésirable » dans Outlook","Par défaut, seuls les admins peuvent libérer un malware en quarantaine","Les messages en quarantaine restent en lecture seule pour tous, admins compris"],"g":2,"e":"La stratégie de quarantaine par défaut des logiciels malveillants (AdminOnlyAccessPolicy) réserve la libération aux administrateurs. Il en va de même par défaut pour le hameçonnage à haut niveau de confiance."},
  {"theme":"securite365","level":"hero","format":"single","q":"Un mail légitime atterrit régulièrement dans le courrier indésirable d'un utilisateur. Que doit-il faire en priorité dans Outlook ?","a":["Utiliser « Signaler » puis « Non indésirable » sur ce message","Désactiver le dossier Courrier indésirable","Créer une règle qui supprime les mails de l'expéditeur","Demander à l'expéditeur de changer d'adresse mail"],"g":0,"e":"Le signalement « Non indésirable » déplace le message et remonte un faux positif à l'équipe sécurité et à Microsoft, ce qui aide à corriger le filtrage."},
  {"theme":"securite365","level":"hero","format":"single","q":"Dans Outlook, la photo de l'expéditeur est remplacée par un point d'interrogation. Qu'est-ce que ça indique ?","a":["L'expéditeur n'a pas encore ajouté de photo à son profil","Le mail contient une pièce jointe que Defender n'a pas analysée","L'expéditeur fait partie de ta liste d'expéditeurs bloqués","Microsoft 365 n'a pas pu authentifier l'expéditeur (SPF, DKIM, DMARC)"],"g":3,"e":"Le « ? » signale un expéditeur non vérifié : le message n'a pas passé les contrôles d'authentification. Ce n'est pas forcément une attaque, mais il faut redoubler de prudence."},
  {"theme":"securite365","level":"hero","format":"single","q":"Tu veux améliorer le Secure Score de ton organisation. Où trouves-tu la liste des mesures recommandées ?","a":["Dans le centre d'administration Exchange, onglet « Flux de courrier »","Dans l'onglet « Actions recommandées » de Secure Score (portail Defender)","Dans les paramètres de confidentialité de chaque application Office","Dans l'Observateur d'événements de Windows, journal Sécurité"],"g":1,"e":"Chaque action recommandée indique les points qu'elle rapporte, son impact sur les utilisateurs et les étapes de mise en œuvre."},
  {"theme":"securite365","level":"super","format":"input","q":"Quelle cmdlet permet de se connecter à Security & Compliance PowerShell (Microsoft Purview) avec le module ExchangeOnlineManagement ?","placeholder":"Nom de la cmdlet","answers":["Connect-IPPSSession"],"e":"Connect-IPPSSession ouvre une session sur Security & Compliance PowerShell (recherches de conformité, étiquettes, DLP…). Connect-ExchangeOnline, elle, se connecte à Exchange Online."},
  {"theme":"securite365","level":"super","format":"single","q":"Tu veux appliquer rapidement la configuration recommandée par Microsoft pour l'anti-spam, l'anti-hameçonnage, Safe Links et Safe Attachments, sans régler chaque stratégie à la main. Tu utilises…","a":["Des règles de flux de courrier Exchange appliquées à tout le tenant","Les actions d'amélioration du rapport Secure Score","Les stratégies de sécurité prédéfinies Standard ou Stricte","La liste d'autorisation/blocage du locataire (TABL)"],"g":2,"e":"Les stratégies de sécurité prédéfinies (Standard et Stricte) appliquent les paramètres recommandés et sont mises à jour par Microsoft. Secure Score ne fait que recommander des actions. La protection intégrée active Safe Links et Safe Attachments par défaut pour les licences Defender pour Office 365."},
  {"theme":"securite365","level":"super","format":"order","q":"Remets dans l'ordre la création d'une stratégie DLP dans le portail Microsoft Purview :","items":["Choisir un modèle (ex. données financières) ou une stratégie personnalisée","Nommer la stratégie et définir son étendue","Sélectionner les emplacements (Exchange, SharePoint, OneDrive, Teams…)","Définir les règles : conditions, actions et conseils de stratégie","Lancer en mode simulation, analyser, puis activer"],"e":"Démarrer en mode simulation permet de mesurer l'impact (faux positifs) avant de bloquer réellement les utilisateurs."},
  {"theme":"securite365","level":"super","format":"multi","q":"Quelles affirmations sur les stratégies d'étiquetage automatique côté service (Microsoft Purview) sont vraies ? (plusieurs réponses)","a":["Elles peuvent être exécutées d'abord en mode simulation","Elles s'appliquent aux emplacements Exchange, SharePoint et OneDrive","Elles ne fonctionnent que si l'utilisateur ouvre le fichier dans une application Office","Elles étiquettent les données au repos sans action de l'utilisateur"],"g":[0,1,3],"e":"L'étiquetage automatique côté service tourne dans le cloud, sur les données au repos et les mails en transit, sans ouverture par l'utilisateur. C'est l'étiquetage côté client qui agit pendant l'édition dans les applications Office."},
  {"theme":"securite365","level":"super","format":"single","q":"Dans Microsoft Secure Score, quels statuts d'une action d'amélioration te rapportent quand même les points sans l'appliquer via le contrôle Microsoft ?","a":["« Résolu par un tiers » et « Résolu par une atténuation alternative »","« Planifié » et « À traiter »","« Risque accepté » uniquement","Aucun : seuls les contrôles détectés par Microsoft comptent"],"g":0,"e":"Si une solution tierce ou une autre mesure couvre le risque, ces statuts attribuent les points. « Risque accepté » n'en rapporte pas, et « Planifié » ne fait que suivre l'action."},
  {"theme":"securite365","level":"super","format":"single","q":"Avec Audit (Standard) de Microsoft Purview, combien de temps les enregistrements d'audit sont-ils conservés par défaut ?","a":["30 jours","90 jours","180 jours","10 ans"],"g":2,"e":"Depuis fin 2023, Audit (Standard) conserve les enregistrements 180 jours. Audit (Premium) va plus loin (un an par défaut pour certaines charges de travail, jusqu'à 10 ans avec un module complémentaire).","maj":{"date":"2023-10-17","texte":"Microsoft fait passer la conservation par défaut d'Audit (Standard) de 90 à 180 jours.","source":"Microsoft Learn","url":"https://learn.microsoft.com/purview/audit-solutions-overview","avant":[1]}},
  {"theme":"securite365","level":"legende","format":"single","q":"Search-UnifiedAuditLog ne renvoie aucun résultat et Get-AdminAuditLogConfig affiche UnifiedAuditLogIngestionEnabled à False. Quelle commande corrige le problème ?","a":["Set-OrganizationConfig -UnifiedAuditLogIngestionEnabled $true","Set-AdminAuditLogConfig -UnifiedAuditLogIngestionEnabled $true","Set-OrganizationConfig -AuditDisabled $false","Get-Mailbox | Set-Mailbox -AuditEnabled $true"],"g":1,"e":"Set-AdminAuditLogConfig -UnifiedAuditLogIngestionEnabled $true, exécutée dans Exchange Online PowerShell, active l'ingestion dans le journal d'audit unifié. Ce paramètre n'existe pas sur Set-OrganizationConfig, dont -AuditDisabled ne gère que l'audit des boîtes au niveau de l'organisation. Set-Mailbox -AuditEnabled ne concerne que l'audit d'une boîte aux lettres."},
  {"theme":"securite365","level":"legende","format":"multi","q":"Un même document est couvert par plusieurs stratégies de rétention Microsoft Purview contradictoires. Quels principes de résolution s'appliquent ? (plusieurs réponses)","a":["La rétention l'emporte sur la suppression","La période de rétention la plus longue l'emporte","Une étendue explicite l'emporte sur une étendue implicite","La stratégie créée le plus récemment l'emporte"],"g":[0,1,2],"e":"Les principes de rétention sont hiérarchisés : rétention avant suppression, rétention la plus longue, inclusion explicite plutôt qu'implicite, puis période de suppression la plus courte. La date de création de la stratégie n'entre pas en jeu."},
  {"theme":"securite365","level":"legende","format":"input","q":"En chasse avancée (Microsoft Defender XDR), quelle table KQL contient les informations sur l'envoi et la livraison des mails (expéditeur, destinataire, verdict, action de livraison) ?","placeholder":"Nom de la table","answers":["EmailEvents"],"e":"EmailEvents regroupe les événements de mail traités par Defender pour Office 365. Les tables EmailUrlInfo, EmailAttachmentInfo et EmailPostDeliveryEvents complètent les détails sur les liens, les pièces jointes et les actions après livraison (ZAP, remédiation)."},
  {"theme":"securite365","level":"legende","format":"single","q":"Tu dois bloquer une URL malveillante pour tout le locataire via la liste d'autorisation/blocage du locataire en PowerShell. Quelle commande utilises-tu ?","a":["Set-AtpPolicyForO365 -Identity Default -BlockUrls <url>","New-SafeLinksPolicy -Name BlocageURL -BlockedUrls <url>","Set-HostedContentFilterPolicy -Identity Default -BlockedUrls <url>","New-TenantAllowBlockListItems -ListType Url -Block -Entries <url>"],"g":3,"e":"New-TenantAllowBlockListItems gère la liste d'autorisation/blocage du locataire (URL, expéditeurs, fichiers). L'ancienne liste BlockUrls de Set-AtpPolicyForO365 a été abandonnée au profit de cette liste."},
  {"theme":"securite365","level":"legende","format":"tf","q":"Une fois qu'un élément est marqué comme enregistrement réglementaire par une étiquette de rétention, même un administrateur général ne peut plus retirer l'étiquette de cet élément.","a":["Vrai","Faux"],"g":0,"e":"C'est ce qui distingue l'enregistrement réglementaire de l'enregistrement simple : l'étiquette ne peut plus être retirée et sa période de rétention ne peut pas être raccourcie. Microsoft recommande de tester avant de l'utiliser, car c'est irréversible."},
  {"theme":"securite365","level":"legende","format":"order","q":"Remets dans l'ordre la purge d'un mail malveillant dans toutes les boîtes via Security & Compliance PowerShell :","items":["Connect-IPPSSession -EnableSearchOnlySession","New-ComplianceSearch avec -ExchangeLocation All et une -ContentMatchQuery précise","Start-ComplianceSearch","Vérifier les résultats avec Get-ComplianceSearch","New-ComplianceSearchAction -Purge -PurgeType HardDelete"],"e":"Depuis le module ExchangeOnlineManagement 3.9.0, ces cmdlets exigent une session ouverte avec -EnableSearchOnlySession. On vérifie toujours le nombre d'éléments trouvés avant de purger, car une requête trop large supprimerait des mails légitimes. -PurgeType SoftDelete laisse les éléments récupérables par l'utilisateur, HardDelete non. La purge retire au maximum 10 éléments par boîte."},
  {"theme":"powerplatform","level":"recrue","format":"single","q":"Quel outil Microsoft 365 sert à automatiser des tâches répétitives, comme enregistrer les pièces jointes d'un mail dans OneDrive ?","a":["Power Apps","Power Automate","Power BI","Microsoft Forms"],"g":1,"e":"Power Automate enchaîne automatiquement des actions entre services. Power Apps sert à créer des applications, Power BI à analyser des données."},
  {"theme":"powerplatform","level":"recrue","format":"single","q":"Dans un flux Power Automate, les étapes qui suivent le déclencheur (envoyer un mail, créer un fichier…) s'appellent des…","a":["connecteurs","environnements","actions","colonnes"],"g":2,"e":"Un flux = un déclencheur suivi d'actions. Les connecteurs, eux, sont les « ponts » vers les services qui fournissent déclencheurs et actions."},
  {"theme":"powerplatform","level":"recrue","format":"single","q":"Que veut dire « low-code », un terme souvent associé à la Power Platform ?","a":["Un langage de programmation simplifié à apprendre avant de commencer","Un script très court à taper dans PowerShell pour tout automatiser","Créer des applis avec peu ou pas de code, visuellement","Une version gratuite et limitée des outils de la Power Platform"],"g":2,"e":"Low-code signifie qu'on construit surtout avec des outils visuels, par glisser-déposer et configuration, avec quelques formules au besoin, sans être développeur."},
  {"theme":"powerplatform","level":"recrue","format":"single","q":"Sur quel site web crées-tu et gères-tu tes flux Power Automate ?","a":["make.powerautomate.com","admin.microsoft.com","portal.azure.com","outlook.office.com"],"g":0,"e":"Le portail des créateurs Power Automate est make.powerautomate.com. admin.microsoft.com est le centre d'administration Microsoft 365."},
  {"theme":"powerplatform","level":"recrue","format":"single","q":"Dans Power Automate, à quoi sert un modèle ?","a":["À acheter une licence premium pour débloquer des connecteurs","À partir d'un flux prêt à l'emploi que tu adaptes","À consulter l'historique des exécutions de tes flux","À bloquer un connecteur jugé risqué dans ton environnement"],"g":1,"e":"Les modèles sont des flux préconstruits pour les scénarios courants : tu choisis, tu connectes tes comptes, tu ajustes en quelques clics."},
  {"theme":"powerplatform","level":"recrue","format":"single","q":"Ton flux n'a pas fait ce que tu attendais. Où regardes-tu en premier ?","a":["Dans le centre d'administration Exchange","Dans la corbeille OneDrive","Dans l'historique des exécutions du flux","Dans les paramètres de Teams"],"g":2,"e":"L'historique des exécutions montre chaque exécution, son statut et l'étape qui a échoué, avec les entrées et sorties de chaque action."},
  {"theme":"powerplatform","level":"recrue","format":"single","q":"Quel outil installe-t-on sur un PC Windows pour automatiser des clics et saisies dans des applications de bureau ?","a":["Power BI Desktop","Power Apps Studio","Le Planificateur de tâches Windows","Power Automate pour le bureau"],"g":3,"e":"Power Automate pour le bureau crée des flux de bureau (RPA) qui pilotent des applications Windows et des sites web comme un humain. Le Planificateur de tâches lance des programmes à heure fixe, mais ne sait pas cliquer ni saisir à ta place."},
  {"theme":"powerplatform","level":"recrue","format":"tf","q":"Une liste SharePoint peut servir de source de données à une application Power Apps.","a":["Vrai","Faux"],"g":0,"e":"Vrai : SharePoint est l'une des sources les plus utilisées pour les apps canevas, et Power Apps peut même générer une app directement à partir d'une liste."},
  {"theme":"powerplatform","level":"recrue","format":"multi","q":"Quels sont les trois types de flux cloud proposés à la création dans Power Automate ? (plusieurs réponses)","a":["Automatisé","Instantané","Planifié","Partagé"],"g":[0,1,2],"e":"Un flux cloud est automatisé (déclenché par un événement), instantané (lancé manuellement) ou planifié (à heure fixe). « Partagé » n'est pas un type de flux."},
  {"theme":"powerplatform","level":"recrue","format":"order","q":"Remets dans l'ordre la création d'un flux automatisé simple :","items":["Ouvrir make.powerautomate.com et cliquer sur « Créer »","Choisir « Flux de cloud automatisé »","Sélectionner le déclencheur, par exemple « Lorsqu'un nouvel e-mail arrive »","Ajouter les actions souhaitées","Enregistrer puis tester le flux"],"e":"On part toujours du type de flux, puis du déclencheur, puis des actions. Le test permet de vérifier l'exécution dans l'historique."},
  {"theme":"powerplatform","level":"recrue","format":"input","q":"Quel connecteur utilises-tu pour déclencher un flux à l'arrivée d'un mail dans ta boîte professionnelle ? (nom du connecteur)","placeholder":"Nom du connecteur","answers":["Office 365 Outlook","Outlook","Office365 Outlook"],"e":"Le connecteur Office 365 Outlook propose le déclencheur « Lorsqu'un nouvel e-mail arrive » pour les boîtes Exchange Online."},
  {"theme":"powerplatform","level":"hero","format":"single","q":"Tu veux qu'un flux envoie une demande de validation à ton manager et attende sa réponse avant de continuer. Quelle action utilises-tu ?","a":["Envoyer un e-mail (V2)","Démarrer et attendre une approbation","Publier un message dans une conversation ou un canal","Retarder"],"g":1,"e":"« Démarrer et attendre une approbation » (connecteur Approbations) met le flux en pause jusqu'à la réponse, visible aussi dans l'app Approbations de Teams."},
  {"theme":"powerplatform","level":"hero","format":"single","q":"Quel contrôle d'un flux répète des actions pour chaque élément renvoyé, par exemple chaque ligne de « Obtenir les éléments » ?","a":["Branche parallèle","Faire jusqu'à","Appliquer à chacun","Commutateur"],"g":2,"e":"« Appliquer à chacun » parcourt un tableau. « Faire jusqu'à » se répète tant qu'une condition n'est pas remplie, une branche parallèle exécute des actions en même temps, et Commutateur sert aux embranchements."},
  {"theme":"powerplatform","level":"hero","format":"single","q":"Qu'est-ce qui distingue une app canevas d'une app pilotée par modèle dans Power Apps ?","a":["Dans une app canevas, tu dessines toi-même chaque écran","Une app canevas ne fonctionne que sur mobile","Une app canevas exige obligatoirement Dataverse","Une app canevas ne peut pas se connecter à SharePoint"],"g":0,"e":"L'app canevas laisse une liberté totale de mise en page, écran par écran, et se connecte à de nombreuses sources. L'app pilotée par modèle génère l'interface à partir des données Dataverse."},
  {"theme":"powerplatform","level":"hero","format":"single","q":"Tu partages ton app canevas basée sur une liste SharePoint, mais un collègue obtient une erreur d'accès aux données. Cause la plus probable ?","a":["Son navigateur n'est pas Microsoft Edge","L'app doit être republiée chaque jour","Il n'a pas de droits sur la liste SharePoint elle-même","Il doit être copropriétaire de l'app pour l'ouvrir"],"g":2,"e":"Partager une app ne donne pas accès aux données : l'utilisateur doit aussi avoir les autorisations sur la liste SharePoint source."},
  {"theme":"powerplatform","level":"hero","format":"single","q":"Dans Power Apps, que fait la formule SubmitForm(EditForm1) ?","a":["Elle vide les champs sans rien enregistrer","Elle enregistre les données du formulaire dans la source","Elle valide les champs puis ouvre l'écran suivant","Elle supprime l'élément sélectionné dans la source"],"g":1,"e":"SubmitForm valide et envoie les modifications du formulaire vers la source de données, sans changer d'écran. Pour vider le formulaire, c'est ResetForm."},
  {"theme":"powerplatform","level":"hero","format":"single","q":"Dans Copilot Studio, comment appelle-t-on les exemples de phrases qui permettent à l'agent de reconnaître une rubrique ?","a":["Des invites système","Des connecteurs","Des variables globales","Des phrases déclencheuses"],"g":3,"e":"Une rubrique (topic) démarre quand la question de l'utilisateur ressemble à ses phrases déclencheuses ; avec l'orchestration générative, sa description joue aussi ce rôle."},
  {"theme":"powerplatform","level":"hero","format":"tf","q":"Un flux instantané peut être partagé en « exécution seule » : les utilisateurs peuvent le lancer sans pouvoir le modifier.","a":["Vrai","Faux"],"g":0,"e":"Vrai : les utilisateurs en exécution seule lancent le flux sans voir ni modifier sa définition, contrairement aux copropriétaires."},
  {"theme":"powerplatform","level":"hero","format":"multi","q":"Parmi ces connecteurs, lesquels sont des connecteurs standard (pas de licence premium) ? (plusieurs réponses)","a":["SharePoint","Office 365 Outlook","SQL Server","HTTP"],"g":[0,1],"e":"SharePoint et Office 365 Outlook sont standard. SQL Server et HTTP sont premium et demandent une licence Power Apps ou Power Automate Premium."},
  {"theme":"powerplatform","level":"hero","format":"input","q":"Dans Power Apps, quelle fonction permet de passer d'un écran à un autre ?","placeholder":"Nom de la fonction","answers":["Navigate","Navigate()"],"e":"Navigate(Écran2) affiche un autre écran, avec une transition facultative. Back() revient à l'écran précédent."},
  {"theme":"powerplatform","level":"super","format":"single","q":"Dans quel centre d'administration gères-tu les environnements et les stratégies de données (DLP) de la Power Platform ?","a":["Le centre d'administration Microsoft 365","Le centre d'administration Power Platform","Le portail Azure","Le portail Microsoft Purview"],"g":1,"e":"Environnements, stratégies DLP, capacité et analyses se gèrent dans le centre d'administration Power Platform (admin.powerplatform.microsoft.com). Les stratégies DLP de Purview concernent d'autres données."},
  {"theme":"powerplatform","level":"super","format":"single","q":"Quelle affirmation sur l'environnement par défaut de la Power Platform est exacte ?","a":["Seuls les administrateurs peuvent y créer des flux","Il doit être créé à la main après l'achat des licences","Tous les utilisateurs du tenant peuvent y créer apps et flux","Il ne peut jamais contenir de base Dataverse"],"g":2,"e":"Chaque tenant a un environnement par défaut où tous les utilisateurs sont créateurs. C'est pour ça qu'on le protège avec des stratégies DLP strictes."},
  {"theme":"powerplatform","level":"super","format":"single","q":"Tu veux passer une app et ses flux d'un environnement de développement vers la production proprement. Que fais-tu ?","a":["Tu partages le lien de l'app aux utilisateurs de production","Tu exportes la liste SharePoint en CSV, puis tu la réimportes","Tu crées un connecteur personnalisé vers la production","Tu les places dans une solution, que tu exportes puis importes"],"g":3,"e":"Les solutions sont le mécanisme de gestion du cycle de vie (ALM) : on exporte généralement une solution managée vers la production."},
  {"theme":"powerplatform","level":"super","format":"single","q":"Une app canevas filtre une liste SharePoint volumineuse et affiche un avertissement de délégation. Qu'est-ce que ça implique ?","a":["Le filtre s'exécute en local, sur les premières lignes seulement","L'utilisateur n'a pas le droit de lire toute la liste SharePoint","Le filtre sera confié à Power Automate, ce qui ralentit l'app","La liste doit être convertie en table Excel pour être filtrée"],"g":0,"e":"SharePoint n'exécute pas une formule non délégable : elle est évaluée localement sur les premières lignes seulement, jusqu'à la limite de lignes de données (500 par défaut, 2 000 au maximum). Les résultats peuvent être incomplets sans erreur visible."},
  {"theme":"powerplatform","level":"super","format":"single","q":"Quelle est la valeur maximale de la « limite de lignes de données » pour les requêtes non délégables dans une app canevas ?","a":["500","1 000","2 000","5 000"],"g":2,"e":"La valeur par défaut est 500 et peut être portée jusqu'à 2 000 dans les paramètres de l'app. Au-delà, il faut des formules délégables."},
  {"theme":"powerplatform","level":"super","format":"single","q":"Un flux de bureau doit tourner la nuit sur une machine sans session utilisateur ouverte. Quel mode d'exécution faut-il ?","a":["Le mode avec assistance (attended)","Le mode sans assistance (unattended)","Le mode enregistreur","Le mode débogage"],"g":1,"e":"Le mode sans assistance ouvre lui-même une session sur la machine inscrite. Le mode avec assistance exige une session active, et l'exécution sans assistance demande une licence adaptée (plan Process)."},
  {"theme":"powerplatform","level":"super","format":"tf","q":"Dans une stratégie DLP, un connecteur du groupe « Professionnel » (Business) peut échanger des données avec un connecteur du groupe « Non professionnel » dans le même flux.","a":["Vrai","Faux"],"g":1,"e":"Faux : une app ou un flux ne peut pas combiner des connecteurs des groupes Professionnel et Non professionnel. Les connecteurs Bloqués ne sont pas utilisables du tout."},
  {"theme":"powerplatform","level":"super","format":"multi","q":"Quels rôles de sécurité Dataverse existent par défaut dans un environnement ? (plusieurs réponses)","a":["Administrateur système","Personnalisateur système","Créateur d'environnement","Administrateur Exchange"],"g":[0,1,2],"e":"Administrateur système, Personnalisateur système et Créateur d'environnement (Environment Maker) sont des rôles d'environnement. Administrateur Exchange est un rôle Microsoft Entra."},
  {"theme":"powerplatform","level":"super","format":"order","q":"Remets dans l'ordre la création d'une stratégie DLP limitée à un environnement :","items":["Ouvrir la section des stratégies de données dans le centre d'administration Power Platform","Créer une nouvelle stratégie et lui donner un nom","Classer les connecteurs : Professionnel, Non professionnel ou Bloqué","Définir l'étendue et ajouter l'environnement ciblé","Vérifier le récapitulatif et créer la stratégie"],"e":"L'assistant suit cet ordre : nom, classement des connecteurs, étendue puis environnements, et enfin vérification."},
  {"theme":"powerplatform","level":"super","format":"input","q":"Quelle cmdlet du module d'administration Power Apps exécutes-tu pour te connecter avant d'utiliser Get-AdminPowerApp ?","placeholder":"Nom de la cmdlet","answers":["Add-PowerAppsAccount"],"e":"Add-PowerAppsAccount ouvre la session sur le tenant ; ensuite Get-AdminPowerApp, Get-AdminFlow ou Get-AdminPowerAppEnvironment deviennent utilisables."},
  {"theme":"powerplatform","level":"legende","format":"single","q":"Tu essaies de placer « Initialiser la variable » à l'intérieur d'une boucle « Appliquer à chacun ». Que se passe-t-il ?","a":["La variable est réinitialisée à chaque itération","C'est impossible : l'initialisation doit se faire au niveau supérieur du flux","Ça fonctionne uniquement si la simultanéité de la boucle est désactivée","La variable devient locale à la boucle"],"g":1,"e":"« Initialiser la variable » n'est autorisée qu'au niveau supérieur du flux, pas dans une boucle, une condition ou une étendue. Dans la boucle, on utilise « Définir la variable »."},
  {"theme":"powerplatform","level":"legende","format":"single","q":"Tu actives la simultanéité sur une boucle « Appliquer à chacun » qui utilise « Définir la variable » à chaque itération, puis relit cette variable. Quel est le risque ?","a":["Le flux bascule automatiquement en connecteur premium","La boucle s'arrête après la première itération, sans erreur","Des valeurs imprévisibles, car les itérations écrasent la variable en même temps","La variable passe en lecture seule pendant la boucle"],"g":2,"e":"Les variables sont globales au flux : en parallèle, une itération peut relire une valeur écrite par une autre. Garde la boucle séquentielle ou utilise des actions Composer, propres à chaque itération. Seules « Incrémenter » et « Décrémenter une variable » restent fiables en parallèle."},
  {"theme":"powerplatform","level":"legende","format":"single","q":"Pour reproduire un bloc try/catch dans Power Automate, tu combines…","a":["un Commutateur sur le code de statut et une variable booléenne","des Étendues et « Configurer l'exécution après »","une boucle « Jusqu'à » et l'action Retarder (nouvelle tentative)","des branches parallèles et l'action Terminer"],"g":1,"e":"Une Étendue « Try » contient les actions ; une Étendue « Catch », dont « Configurer l'exécution après » est réglé sur « a échoué » ou « a expiré », gère l'erreur. Une boucle avec Retarder ne fait que réessayer."},
  {"theme":"powerplatform","level":"legende","format":"single","q":"Un flux déclenché à chaque modification d'un élément SharePoint ne doit démarrer que si la colonne Statut vaut « Validé », sans créer d'exécutions inutiles. Que configures-tu ?","a":["Une condition de déclencheur dans les paramètres du déclencheur","Une action Condition placée juste après le déclencheur","Un filtre sur la vue par défaut de la liste","Une stratégie DLP sur le connecteur SharePoint"],"g":0,"e":"Une condition de déclencheur empêche le flux de démarrer si l'expression est fausse. Une action Condition, elle, laisse le flux s'exécuter à chaque modification."},
  {"theme":"powerplatform","level":"legende","format":"single","q":"Le créateur d'une app canevas critique quitte l'entreprise. Quelle cmdlet permet de réaffecter l'app à un nouveau propriétaire ?","a":["Set-PowerAppOwner","Grant-PowerAppOwnership","Update-MgApplicationOwner","Set-AdminPowerAppOwner"],"g":3,"e":"Set-AdminPowerAppOwner (module Microsoft.PowerApps.Administration.PowerShell) prend -AppName, -EnvironmentName et -AppOwner. Les cmdlets Mg ciblent les applications Entra ID, pas Power Apps."},
  {"theme":"powerplatform","level":"legende","format":"single","q":"Deux stratégies DLP couvrent le même environnement : l'une classe un connecteur en Non professionnel, l'autre le bloque. Quel est le résultat ?","a":["La stratégie créée en dernier l'emporte","La stratégie au niveau de l'environnement l'emporte sur celle du tenant","Le connecteur est bloqué : c'est la combinaison la plus restrictive qui s'applique","Le connecteur reste utilisable en Non professionnel"],"g":2,"e":"Quand plusieurs stratégies s'appliquent, elles se cumulent et la plus restrictive gagne. Il n'y a pas de priorité par date ni par niveau."},
  {"theme":"powerplatform","level":"legende","format":"single","q":"Dans une stratégie DLP, comment autoriser le connecteur HTTP uniquement vers certains domaines ?","a":["Avec le filtrage des points de terminaison","Avec le contrôle des actions du connecteur","Avec l'isolation du locataire","Avec une stratégie d'accès conditionnel Entra ID"],"g":0,"e":"Le filtrage des points de terminaison autorise ou refuse des URL précises pour certains connecteurs (HTTP, SQL Server…). Le contrôle des actions bloque des actions, pas des destinations."},
  {"theme":"powerplatform","level":"legende","format":"tf","q":"Dans une stratégie DLP, n'importe quel connecteur peut être placé dans le groupe « Bloqué ».","a":["Vrai","Faux"],"g":1,"e":"Faux : certains connecteurs Microsoft essentiels, comme SharePoint ou Microsoft Dataverse, ne peuvent pas être bloqués ; on peut seulement les classer Professionnel ou Non professionnel."},
  {"theme":"powerplatform","level":"legende","format":"multi","q":"Quels composants d'une solution permettent de déployer un flux dans un autre environnement sans modifier sa définition ? (plusieurs réponses)","a":["Les variables d'environnement","Les références de connexion","Les stratégies DLP","Les groupes de sécurité Entra ID"],"g":[0,1],"e":"Les variables d'environnement externalisent les valeurs (URL de site, ID de liste) et les références de connexion découplent le flux des connexions, reliées à l'import."},
  {"theme":"powerplatform","level":"legende","format":"order","q":"Remets dans l'ordre le déplacement d'une solution avec Power Platform CLI :","items":["S'authentifier sur l'environnement source avec pac auth create","Exporter la solution avec pac solution export","Sélectionner le profil de l'environnement cible avec pac auth select","Importer la solution avec pac solution import"],"e":"pac auth gère les profils de connexion ; on exporte depuis la source, on bascule de profil, puis on importe le fichier .zip dans la cible."},
  {"theme":"powerplatform","level":"legende","format":"input","q":"Quel module PowerShell fournit les cmdlets Get-AdminFlow et Get-AdminPowerApp ?","placeholder":"Nom du module","answers":["Microsoft.PowerApps.Administration.PowerShell"],"e":"Microsoft.PowerApps.Administration.PowerShell est le module d'administration ; Microsoft.PowerApps.PowerShell couvre les cmdlets côté créateur."}
);
